/* ================================================================= sauvegarde */
static uint16_t crc16(const uint8_t *p, int n) {
    uint16_t c = 0xFFFF;
    while (n--) { c ^= *p++; for (int i = 0; i < 8; i++) c = (c & 1) ? (uint16_t)((c >> 1) ^ 0xA001) : (uint16_t)(c >> 1); }
    return c;
}
static void save_defaults(void) {
    memset(&G.sv, 0, sizeof G.sv);
    G.sv.magic = SAVE_MAGIC; G.sv.version = 2; G.sv.opt_fx = 1;
    G.sv.unlocked = (uint16_t)((1 << WP_SWORD) | (1 << WP_DAGGER)); G.sv.found = G.sv.unlocked;
}
static void save_load(void) {
    Save t;
    int n = plat_load(&t, (int)sizeof t);
    if (n == (int)sizeof t && t.magic == SAVE_MAGIC && t.crc == crc16((const uint8_t *)&t, (int)sizeof t - 2)) {
        G.sv = t; G.save_ok = 1;
        G.sv.unlocked |= (uint16_t)((1 << WP_SWORD) | (1 << WP_DAGGER));
    } else { save_defaults(); G.save_ok = (n >= 0); }
}
void save_store(void) {
    G.sv.crc = crc16((const uint8_t *)&G.sv, (int)sizeof G.sv - 2);
    G.save_ok = (plat_store(&G.sv, (int)sizeof G.sv) == 0);
}

/* ================================================================= objets : niveau I..XV et qualite + / ++ / S / L */
static const char *const ROM[16] = { "", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X", "XI", "XII", "XIII", "XIV", "XV" };
const char *roman(int n) { return ROM[clampi(n, 0, 15)]; }
void item_label(const Item *it, char *out) {
    static const char *const Q[5] = { "", "+", "++", "S", "L" };
    const char *r = roman(it->lvl), *q = Q[it->q > 4 ? 0 : it->q];
    int i = 0;
    while (*r) out[i++] = *r++;
    while (*q) out[i++] = *q++;
    out[i] = 0;
}
int item_power(const Item *it) {
    static const uint8_t QB[5] = { 0, 2, 4, 6, 6 };
    return it->lvl + QB[it->q > 4 ? 0 : it->q];
}
void item_make(Item *it, int id, int bonus, int force_q) {
    int ql = G.sv.up[UP_QUAL], r = rn(100), q = 0;
    it->id = (uint8_t)id;
    it->lvl = (uint8_t)clampi(1 + 2 * G.zone + bonus + rn(3), 1, 15);
    if (r < 4 * ql) q = 3;
    else if (r < 4 * ql + 4 + 6 * ql) q = 2;
    else if (r < 4 * ql + 4 + 6 * ql + 14 + 10 * ql) q = 1;
    it->q = (uint8_t)(force_q >= 0 ? force_q : q);
}
int random_weapon(int not_a, int not_b) {
    int w, tries = 0;
    do {
        do { w = rn(WP_COUNT); } while (!((G.sv.unlocked >> w) & 1));
        tries++;
    } while ((w == not_a || w == not_b) && tries < 12);
    return w;
}
int has_mut(int id) {
    for (int i = 0; i < G.mut_n; i++) if (G.mut[i] == id) return 1;
    return 0;
}

/* ================================================================= effets visuels */
static int pa_next;
static Part *new_part(void) {
    Part *a = 0;
    for (int i = 0; i < MAX_PA; i++) if (G.pa[i].life == 0) { a = &G.pa[i]; break; }
    if (!a) { a = &G.pa[pa_next]; pa_next = (pa_next + 1) % MAX_PA; }
    memset(a, 0, sizeof *a);
    return a;
}
void add_part(int kind, int x, int y, int vx, int vy, int life, int col) {
    Part *a = new_part();
    a->x = F(x); a->y = F(y); a->vx = (int16_t)vx; a->vy = (int16_t)vy;
    a->life = (uint8_t)life; a->max = (uint8_t)life; a->kind = (uint8_t)kind; a->col = (uint8_t)col;
}
static void fx_set(int sb, int nf, int x, int y, int delay, int flip) {
    if (!G.sv.opt_fx && sb != SB_FX_SLASH && sb != SB_FX_SMASH && sb != SB_FX_EXPL) return;
    Part *a = new_part();
    a->x = F(x); a->y = F(y); a->life = (uint8_t)(nf * delay); a->max = a->life; a->kind = PA_FX;
    a->col = (uint8_t)flip; a->nf = (uint8_t)nf; a->val = (uint8_t)delay; a->num = (int16_t)sb;
}
void add_fxf(int sb, int nf, int x, int y, int delay, int flip) { fx_set(sb, nf, x, y, delay, flip); }
void add_fx(int sb, int nf, int x, int y, int delay) { fx_set(sb, nf, x, y, delay, 0); }
void add_num(int x, int y, int val, int col) {
    Part *a = new_part();
    if (val > 999) val = 999;
    a->x = F(x); a->y = F(y); a->vy = -10; a->life = 26; a->max = 26; a->kind = PA_NUM; a->col = (uint8_t)col; a->num = (int16_t)val;
}
void burst(int x, int y, int n, int col) {
    if (!G.sv.opt_fx) return;
    for (int i = 0; i < n; i++) add_part(PA_SPARK, x, y, rn(81) - 40, -rn(70) - 10, 10 + rn(10), col);
}

/* ================================================================= physique des boites */
int tile_at(int tx, int ty) {
    if (tx < 0 || tx >= G.lvw || ty < 0) return TL_SOLID;
    if (ty >= LV_H) return TL_EMPTY;
    return G.map[ty][tx];
}
int is_solid(int t) { return t == TL_SOLID || t == TL_GATE; }

int move_box(int32_t *x, int32_t *y, int32_t *vx, int32_t *vy, int w, int h, int drop) {
    int fl = 0, hw = w / 2;
    if (*vx) {
        int32_t nx = *x + *vx;
        int x0 = PX(nx) - hw, x1 = x0 + w - 1, y0 = PX(*y) - h, y1 = PX(*y) - 1;
        int tx = (*vx > 0) ? (x1 >> 4) : (x0 >> 4), hit = 0;
        for (int ty = (y0 >> 4); ty <= (y1 >> 4); ty++) if (is_solid(tile_at(tx, ty))) { hit = 1; break; }
        if (hit) { nx = (*vx > 0) ? F(tx * TS - hw) : F((tx + 1) * TS + hw); *vx = 0; fl |= MB_WALL; }
        *x = nx;
    }
    if (*vy) {
        int32_t ny = *y + *vy;
        int x0 = PX(*x) - hw, x1 = x0 + w - 1, tx0 = x0 >> 4, tx1 = x1 >> 4;
        if (*vy > 0) {
            int feet = PX(ny), oldfeet = PX(*y), ty = (feet - 1) >> 4, hit = 0;
            for (int tx = tx0; tx <= tx1 && !hit; tx++) {
                int t = tile_at(tx, ty);
                if (is_solid(t)) hit = 1;
                else if (t == TL_PLAT && !drop && oldfeet <= ty * TS && feet > ty * TS) hit = 1;
            }
            if (hit) { ny = F(ty * TS); *vy = 0; fl |= MB_GROUND; }
        } else {
            int top = PX(ny) - h, ty = top >> 4, hit = 0;
            for (int tx = tx0; tx <= tx1 && !hit; tx++) if (is_solid(tile_at(tx, ty))) hit = 1;
            if (hit) { ny = F((ty + 1) * TS + h); *vy = 0; fl |= MB_CEIL; }
        }
        *y = ny;
    }
    return fl;
}

int player_box_overlap(int x, int y, int w, int h) {
    int px = PX(G.p.x), py = PX(G.p.y);
    return x < px + 5 && x + w > px - 5 && y < py && y + h > py - 20;
}

/* ================================================================= niveaux semi-aleatoires + passages */
static int pick_enemy(int zone) {
    int tot = 0;
    for (int i = 0; i < 9; i++) tot += EW[zone][i];
    int r = rn(tot);
    for (int i = 0; i < 9; i++) { if (r < EW[zone][i]) return i; r -= EW[zone][i]; }
    return ET_JAIL;
}

static void level_reset(int zone) {
    memset(G.map, 0, sizeof G.map); memset(G.en, 0, sizeof G.en); memset(G.pr, 0, sizeof G.pr);
    memset(G.pa, 0, sizeof G.pa); memset(G.pk, 0, sizeof G.pk);
    G.zone = (uint8_t)zone; G.arena_on = 0; G.boss_alive = 0; G.boss_idx = -1; G.arena_x0 = -1;
    G.door_tx = G.door_ty = -1; G.torch_n = 0; G.passage = 0; G.hint_t = 0;
}
static void level_finish_player(void) {
    Player *p = &G.p;
    p->vx = p->vy = 0; p->st = PS_NORMAL; p->inv = 60; p->t = p->atk_t = p->hold = p->buf_atk = 0; p->ground = 0; p->hitmask = 0; p->guard = 0;
    G.cam_x = F(imax(0, imin(PX(p->x) - 160, G.lvw * TS - SCR_W)));
}

void level_build(int zone) {
    level_reset(zone);
    G.nrooms = ZONE_ROOMS[zone]; G.lvw = (int16_t)(G.nrooms * ROOM_W);
    int seq[MAX_ROOMS], last = -1, n = G.nrooms;
    seq[0] = 0; seq[n - 1] = ZONE_ARENA[zone] ? 2 : 1;
    for (int i = 1; i < n - 1; i++) { int r; do { r = 3 + rn(10); } while (r == last); seq[i] = r; last = r; }
    int pct = 62 + 7 * zone;
    for (int i = 0; i < n; i++) {
        for (int y = 0; y < LV_H; y++) for (int x = 0; x < ROOM_W; x++) {
            char ch = DC_ROOMS[seq[i]][y][x];
            int tx = i * ROOM_W + x, t = TL_EMPTY;
            switch (ch) {
                case '#': t = TL_SOLID; break;
                case '=': t = TL_PLAT; break;
                case '^': t = TL_SPIKE; break;
                case 'D': t = TL_DOOR; break;
                case 'T': t = TL_TORCH; if (G.torch_n < 24) { G.torch_x[G.torch_n] = (int16_t)(tx * TS + 4); G.torch_y[G.torch_n] = (int16_t)(y * TS + 6); G.torch_n++; } break;
                default: break;
            }
            G.map[y][tx] = (uint8_t)t;
            int cx = tx * TS + 8, fy = (y + 1) * TS;
            if (ch == 'S') { G.p.x = F(cx); G.p.y = F(fy); }
            else if (ch == 'e' && rn(100) < pct) spawn_enemy(pick_enemy(zone), tx, y, zone);
            else if (ch == 'E') spawn_enemy(pick_enemy(zone), tx, y, zone);
            else if (ch == 'c') add_pick(PK_CHEST, cx, fy, 0, 0, 0);
            else if (ch == 'f') add_pick(PK_FLASK, cx, fy - 6, 0, 0, 0);
            else if (ch == 'h') add_pick(PK_HEART, cx, fy - 6, 0, 0, 0);
            else if (ch == 'o') { for (int k = -1; k <= 1; k++) add_pick(PK_COIN, cx + k * 10, fy - 8, 1, 0, 0); }
            else if (ch == 'B') {
                spawn_enemy(zone == 2 ? ET_GOB : ET_KING, tx, y, zone);
                for (int k = 0; k < MAX_EN; k++) if (G.en[k].alive && G.en[k].type >= ET_GOB) { G.boss_idx = (int16_t)k; G.en[k].st = ES_SLEEP; }
            }
            else if (ch == 'd') { G.door_tx = (int16_t)tx; G.door_ty = (int16_t)y; }
        }
        if (seq[i] == 2) G.arena_x0 = (int16_t)(i * ROOM_W * TS);
    }
    for (int y = 0; y < LV_H; y++) { G.map[y][0] = TL_SOLID; G.map[y][G.lvw - 1] = TL_SOLID; }
    if (zone == 2) for (int x = 0; x < G.lvw; x++) if (G.map[13][x] == TL_EMPTY && G.map[14][x] == TL_EMPTY) { G.map[13][x] = TL_TOXIC; G.map[14][x] = TL_SOLID; }
    level_finish_player();
    G.hint_t = zone == 0 ? 260 : 0;
    banner(ZONE_NAME[zone], 100);
}

static void build_passage(int zone) {          /* salle sure : PNJ des cellules (Passeur) et des mutations (Oracle) */
    level_reset(zone);
    G.passage = 1; G.nrooms = 1; G.lvw = ROOM_W;
    for (int y = 0; y < LV_H; y++) for (int x = 0; x < ROOM_W; x++) {
        char ch = DC_ROOMS[13][y][x];
        int t = TL_EMPTY, cx = x * TS + 8, fy = (y + 1) * TS;
        switch (ch) {
            case '#': t = TL_SOLID; break;
            case 'D': t = TL_DOOR; break;
            case 'T': t = TL_TORCH; if (G.torch_n < 24) { G.torch_x[G.torch_n] = (int16_t)(x * TS + 4); G.torch_y[G.torch_n] = (int16_t)(y * TS + 6); G.torch_n++; } break;
            case 'S': G.p.x = F(cx); G.p.y = F(fy); break;
            case 'N': add_pick(PK_NPC, cx, fy, 0, 0, 0); break;
            case 'M': add_pick(PK_NPC, cx, fy, 1, 0, 0); break;
            default: break;
        }
        G.map[y][x] = (uint8_t)t;
    }
    for (int y = 0; y < LV_H; y++) { G.map[y][0] = TL_SOLID; G.map[y][G.lvw - 1] = TL_SOLID; }
    level_finish_player();
    banner("PASSAGE", 90);
}

/* ================================================================= joueur */
#define P_W 10
#define P_H 20
#define GRAV 9
#define JUMP_V 124
#define JUMP2_V 104
#define MAXRUN 42
#define MAXFALL 140
#define HOLD_T 14

static void run_end(int win);
static void leave_passage(void);
static void zone_clear(void);

static const Wpn *cur_wpn(void) { return &WPN[G.p.w[G.p.cur].id]; }
static const Atk *cur_atk(const Wpn *w) { const Player *p = &G.p; return p->atk_b ? &w->b : (p->heavy ? &w->h : &w->l); }

static int dmg_of(const Atk *a, const Item *it) {
    int d = a->dmg * (100 + 6 * (item_power(it) - 1)) / 100;
    d = d * (100 + 8 * G.sv.up[UP_DMG]) / 100;
    int pct = 100 + G.p.buff_pct + (has_mut(MU_COMBO) ? 5 * G.p.combo : 0);
    return imax(1, d * pct / 100);
}

static void start_attack(int heavy, int b) {
    Player *p = &G.p; const Wpn *w = cur_wpn();
    int now = b ? 2 : 1;
    p->st = PS_ATK; p->atk_t = 0; p->heavy = (uint8_t)heavy; p->atk_b = (uint8_t)b; p->hitmask = 0; p->buf_atk = 0;
    if (G.keys & K_L) p->dir = -1; else if (G.keys & K_R) p->dir = 1;
    p->crit_next = (uint8_t)(w->kind == WK_DUAL && p->last_atk && p->last_atk != now);   /* faux-serres : critique en alternant */
    p->last_atk = (uint8_t)now; p->dual_t = 50;
    p->buff_pct = 0;
    if (has_mut(MU_REVENGE) && p->mt_veng > 0) { p->buff_pct += 60; p->mt_veng = 0; }
    if (has_mut(MU_DISENGAGE) && p->mt_dis > 0) { p->buff_pct += 40; p->mt_dis = 0; }
    if (has_mut(MU_CALM) && p->mt_calm >= 20) { p->buff_pct += 50; p->mt_calm = 0; }
    const Atk *a = cur_atk(w);
    if (a->lunge) p->vx = p->dir * a->lunge * 16;
}

static void nearest_target(int range_x, int range_y, int dir, Ent **out) {
    int best = 99999; *out = 0;
    int px = PX(G.p.x), py = PX(G.p.y) - 10;
    for (int i = 0; i < MAX_EN; i++) {
        Ent *e = &G.en[i];
        if (!e->alive || e->st == ES_DEAD || e->st == ES_SLEEP) continue;
        int dx = PX(e->x) - px, dy = PX(e->y) - 10 - py;
        if (dir && dx * dir < -8) continue;
        if (iabs(dx) > range_x || iabs(dy) > range_y) continue;
        if (iabs(dx) < best) { best = iabs(dx); *out = e; }
    }
}

static void strike(Ent *e, const Atk *a, const Item *it, int d, int crit, int dir) {
    Player *p = &G.p;
    if (it->q == 4 && WPN[it->id].leg == LG_CRIT3 && (++p->crit3 % 3) == 0) crit = 1;
    if (crit) d *= 2;
    g_crit = (uint8_t)crit;
    hurt_enemy(e, d, dir, a->kb, a->stun);
    g_crit = 0;
    if (e->st != ES_DEAD) {
        if (has_mut(MU_BLEED) && !e->burn) e->burn = 90;
        if (it->q == 4 && WPN[it->id].leg == LG_IGNITE) e->burn = 90;
    }
    if (it->q == 4 && WPN[it->id].leg == LG_VAMP) p->hp = (int16_t)imin(p->maxhp, p->hp + 1);
    if (has_mut(MU_COMBO)) { if (p->combo < 5) p->combo++; p->combo_t = 45; }
    G.hitstop = p->heavy ? 4 : 3;
}

static void attack_active(const Wpn *w, const Atk *a) {
    Player *p = &G.p; const Item *it = &p->w[p->cur];
    int px = PX(p->x), py = PX(p->y), dir = p->dir, dm = dmg_of(a, it), id = it->id;
    if (w->kind == WK_MELEE || w->kind == WK_SHIELD || w->kind == WK_DUAL) {
        int x0, x1, aoe = (id == WP_HAMMER && p->heavy);
        if (aoe) { x0 = px - a->reach; x1 = px + a->reach; }
        else if (dir > 0) { x0 = px + 2; x1 = px + 2 + a->reach; } else { x1 = px - 2; x0 = px - 2 - a->reach; }
        if (p->atk_t == a->a0) {
            if (id == WP_HAMMER) { add_fxf(SB_FX_SMASH, SN_FX_SMASH, px + (aoe ? 0 : dir * 24), py - 8, 3, 0); G.shake = aoe ? 8 : 5; }
            else if (id == WP_SWORD || id == WP_SCYTHE) add_fxf(SB_FX_SLASH, SN_FX_SLASH, px + dir * 11, py - 12, p->heavy ? 3 : 2, dir < 0);
            else add_fxf(SB_FX_HIT, 1, px + dir * 18, py - 12, 2, 0);
        }
        for (int i = 0; i < MAX_EN; i++) {
            Ent *e = &G.en[i];
            if (!e->alive || e->st == ES_DEAD || e->st == ES_SLEEP || (p->hitmask & (1u << i))) continue;
            int ew = ent_w(e), eh = ent_h(e), ex = PX(e->x), ey = PX(e->y);
            if (e->type == ET_BAT) ey += 6;
            if (x0 < ex + ew / 2 && x1 > ex - ew / 2 && py + a->y0 < ey && py + a->y1 > ey - eh) {
                int d = dm, crit = p->crit_next;
                if (id == WP_DAGGER && e->dir == dir) crit = 1;                         /* coup dans le dos */
                if (id == WP_RAPIER && iabs(ex - px) > a->reach * 70 / 100) d = d * 8 / 5;   /* pointe de la rapiere */
                p->hitmask |= (1u << i);
                strike(e, a, it, d, crit, dir);
                if (id != WP_HAMMER) G.shake = imax(G.shake, 2);
            }
        }
    } else if (p->atk_t == a->a0) {
        int sx = px + dir * 10, sy = py - 12;
        if (w->kind == WK_BOW) {
            if (id == WP_XBOW) add_proj(PJ_XBOLT, 0, sx, sy, dir * 150, 0, dm, 70, dir);
            else add_proj(p->heavy ? PJ_PARROW : PJ_ARROW, 0, sx, sy, dir * (p->heavy ? 144 : 112), 0, dm, 70, dir);
        } else if (w->kind == WK_FIRE) {
            if (!p->heavy) add_proj(PJ_FIRE, 0, sx, sy, dir * 80, 0, dm, 70, dir);
            else for (int k = -1; k <= 1; k++) add_proj(PJ_FIRE, 0, sx, sy, dir * 80, k * 18, dm, 70, dir);
        } else {                                                                      /* WK_ELEC */
            Ent *t1 = 0, *t2 = 0;
            if (!p->heavy) {
                nearest_target(150, 60, dir, &t1);
                if (t1) {
                    add_part(PA_LINE, sx, sy, PX(t1->x), PX(t1->y) - 10, 5, 0);
                    hurt_enemy(t1, dm, dir, 1, 8);
                    int idx = (int)(t1 - G.en);
                    for (int i = 0; i < MAX_EN; i++) {
                        Ent *e = &G.en[i];
                        if (i == idx || !e->alive || e->st == ES_DEAD || e->st == ES_SLEEP) continue;
                        if (iabs(PX(e->x) - PX(t1->x)) < 56 && iabs(PX(e->y) - PX(t1->y)) < 40) { t2 = e; break; }
                    }
                    if (t2) { add_part(PA_LINE, PX(t1->x), PX(t1->y) - 10, PX(t2->x), PX(t2->y) - 10, 5, 0); hurt_enemy(t2, imax(1, dm / 2), dir, 0, 6); }
                } else add_part(PA_LINE, sx, sy, sx + dir * 70, sy + rn(9) - 4, 4, 0);
            } else {
                for (int i = 0; i < MAX_EN; i++) {
                    Ent *e = &G.en[i];
                    if (!e->alive || e->st == ES_DEAD || e->st == ES_SLEEP) continue;
                    if (iabs(PX(e->x) - px) < 150 && iabs(PX(e->y) - py) < 80) {
                        add_part(PA_LINE, PX(e->x), py - 120, PX(e->x), PX(e->y) - 8, 6, 0);
                        hurt_enemy(e, dm, dir, 1, 10);
                    }
                }
                G.shake = 5;
            }
        }
    }
}

static int on_plat(void) {
    Player *p = &G.p; int feet = PX(p->y), x0 = PX(p->x) - 5, x1 = PX(p->x) + 4, plat = 0;
    if (feet % TS) return 0;
    for (int tx = x0 >> 4; tx <= (x1 >> 4); tx++) {
        int t = tile_at(tx, feet >> 4);
        if (is_solid(t)) return 0;
        if (t == TL_PLAT) plat = 1;
    }
    return plat;
}

static void player_respawn_room(void) {
    Player *p = &G.p;
    int room = clampi(PX(p->x) / (ROOM_W * TS), 0, G.nrooms - 1);
    p->x = F(room * ROOM_W * TS + 24); p->y = F(13 * TS); p->vx = p->vy = 0; p->inv = 50; p->st = PS_NORMAL; p->atk_t = 0;
}

int player_parry_window(int from_x) {
    Player *p = &G.p;
    return p->guard && p->guard_t <= 8 && ((from_x - PX(p->x)) * p->dir) >= -3;
}

void on_kill_hooks(void) {
    Player *p = &G.p;
    if (has_mut(MU_INSTINCT)) { p->hp = (int16_t)imin(p->maxhp, p->hp + 4); add_num(PX(p->x), PX(p->y) - 26, 4, 3); }
    if (has_mut(MU_ADREN)) p->mt_adr = 90;
}

static void open_npc(void) {
    Player *p = &G.p;
    for (int i = 0; i < MAX_PK; i++) {
        Pick *k = &G.pk[i];
        if (k->life && k->kind == PK_NPC && iabs(PX(k->x) - PX(p->x)) < 22) {
            G.in_run = 1; G.menu_sel = 0; G.menu_sub = 0;
            G.scene = (k->val == 0) ? SC_SHOP : SC_MUT;
            return;
        }
    }
}

static void player_update(void) {
    Player *p = &G.p; uint16_t k = G.keys, pr = G.pressed;
    const Wpn *w;
    p->anim++;
    if (p->st == PS_DEAD) {
        p->dead_t++; p->vy = imin(p->vy + GRAV, MAXFALL);
        p->vx = p->vx * 7 / 8;
        move_box(&p->x, &p->y, &p->vx, &p->vy, P_W, P_H, 0);
        return;
    }
    if (p->inv > 0) p->inv--;
    if (p->roll_cd > 0) p->roll_cd--;
    if (p->atk_cd > 0) p->atk_cd--;
    if (p->drop_t > 0) p->drop_t--;
    if (p->flip_t > 0) p->flip_t--;
    if (p->swap_t > 0) p->swap_t--;
    if (p->mt_veng > 0) p->mt_veng--;
    if (p->mt_dis > 0) p->mt_dis--;
    if (p->mt_adr > 0) p->mt_adr--;
    if (p->combo_t > 0 && --p->combo_t == 0) p->combo = 0;
    if (p->dual_t > 0 && --p->dual_t == 0) p->last_atk = 0;
    if (p->ground) { p->coyote = 5; p->jumps = 0; } else if (p->coyote > 0) p->coyote--;
    if (!p->ground && p->coyote == 0 && p->jumps == 0) p->jumps = 1;
    if (pr & K_U) p->jbuf = 5; else if (p->jbuf > 0) p->jbuf--;
    if (p->ground && p->st == PS_NORMAL && !(k & (K_L | K_R))) { if (p->mt_calm < 60) p->mt_calm++; } else if (p->st != PS_NORMAL || (k & (K_L | K_R))) p->mt_calm = 0;

    w = cur_wpn();
    int dual = (w->kind == WK_DUAL);
    if (w->kind == WK_SHIELD && (k & K_OK) && p->st == PS_NORMAL && !G.passage) { p->guard = 1; p->guard_t++; } else { p->guard = 0; p->guard_t = 0; }

    if (G.passage && (pr & K_OK) && p->st == PS_NORMAL) { open_npc(); if (G.scene != SC_PLAY) return; }

    /* ---- armes : changer d'arme, 2e attaque de la faux-serres, fiole */
    if (p->st == PS_NORMAL) {
        if ((pr & K_SWAP) && !G.passage) {
            if (dual) { if (p->atk_cd == 0) start_attack(0, 1); }
            else if (p->swap_t == 0) {
                char buf[32], lab[8]; const char *nm = WPN[p->w[p->cur ^ 1].id].name; int i = 0;
                p->cur ^= 1; p->swap_t = 12;
                item_label(&p->w[p->cur], lab);
                while (*nm && i < 22) { buf[i] = *nm++; i++; }
                buf[i++] = ' '; for (int j = 0; lab[j] && i < 31; j++) buf[i++] = lab[j];
                buf[i] = 0; msg(buf);
            }
        }
        if ((pr & K_FLASK) && p->flasks > 0 && p->hp < p->maxhp) {
            int heal = p->maxhp * (has_mut(MU_GLUTTON) ? 65 : 50) / 100;
            p->hp = (int16_t)imin(p->maxhp, p->hp + heal); p->flasks--;
            add_num(PX(p->x), PX(p->y) - 26, heal, 3); burst(PX(p->x), PX(p->y) - 12, 8, 3);
        }
    }

    /* ---- attaque : declenchee au relachement de OK (maintenu = attaque lourde ; bouclier : maintenu = garde) */
    if (!G.passage) {
        if (k & K_OK) { if (p->hold < 250) p->hold++; }
        if ((G.prev & K_OK) && !(k & K_OK)) {
            int hold = p->hold;
            if (p->st == PS_NORMAL && p->atk_cd == 0) {
                if (w->kind == WK_SHIELD) { if (hold < HOLD_T) start_attack(0, 0); }
                else start_attack(hold >= HOLD_T, 0);
            } else if (p->st == PS_ATK) p->buf_atk = 10;
            p->hold = 0;
        }
        if (p->st == PS_NORMAL && p->buf_atk > 0 && p->atk_cd == 0 && p->hold == 0 && w->kind != WK_SHIELD) start_attack(0, 0);
    }
    if (p->buf_atk > 0) p->buf_atk--;
    w = cur_wpn();

    /* ---- esquive (Retour) */
    if ((pr & K_BACK) && p->roll_cd == 0 && p->st != PS_HURT && p->st != PS_ROLL) {
        const Atk *a = cur_atk(w);
        if (p->st == PS_NORMAL || (p->st == PS_ATK && p->atk_t >= a->a1)) {
            int d = (k & K_L) ? -1 : (k & K_R) ? 1 : p->dir;
            p->dir = (int8_t)d; p->st = PS_ROLL; p->t = 0; p->atk_t = 0; p->hold = 0; p->guard = 0;
            p->inv = (int16_t)imax(p->inv, 10 + 2 * G.sv.up[UP_DODGE]);
            add_part(PA_SMOKE, PX(p->x), PX(p->y) - 2, -d * 12, -4, 14, 0);
        }
    }

    /* ---- horizontal */
    int want = ((k & K_R) ? 1 : 0) - ((k & K_L) ? 1 : 0);
    if (p->st == PS_ROLL) {
        p->vx = p->dir * 67; p->t++;
        if (p->t >= 14) { p->st = PS_NORMAL; p->roll_cd = (int16_t)(20 - 3 * G.sv.up[UP_DODGE]); p->vx = p->dir * 20; if (has_mut(MU_DISENGAGE)) p->mt_dis = 60; }
    } else if (p->st == PS_HURT) {
        p->t--; p->vx = p->vx * 15 / 16; if (p->t <= 0) p->st = PS_NORMAL;
    } else {
        const Atk *a = cur_atk(w);
        int lunging = (p->st == PS_ATK && a->lunge && p->atk_t <= a->a1);
        int maxs = MAXRUN;
        if (p->st == PS_ATK) maxs = MAXRUN * 2 / 5;
        else if (p->guard) maxs = MAXRUN / 2;
        else if (has_mut(MU_ADREN) && p->mt_adr > 0) maxs = MAXRUN * 120 / 100;
        if (!lunging) {
            if (want) {
                int target = want * maxs, acc = p->ground ? 7 : 5;
                if (p->vx < target) p->vx = imin(target, (int)p->vx + acc); else if (p->vx > target) p->vx = imax(target, (int)p->vx - acc);
                if (p->st == PS_NORMAL) p->dir = (int8_t)want;
            } else {
                int fr = p->ground ? 8 : 3;
                if (p->vx > 0) p->vx = imax(0, (int)p->vx - fr); else if (p->vx < 0) p->vx = imin(0, (int)p->vx + fr);
            }
        }
        if (p->st == PS_ATK) {
            p->atk_t++;
            if (p->atk_t >= a->a0 && p->atk_t <= a->a1) attack_active(w, a);
            if (p->atk_t >= a->total) { p->st = PS_NORMAL; p->atk_cd = 0; }
        }
    }

    /* ---- saut / double saut / traversee de plateforme */
    if (p->st == PS_NORMAL || p->st == PS_ATK) {
        if ((pr & K_D) && p->ground && on_plat()) { p->drop_t = 10; p->ground = 0; p->y += F(2); p->jbuf = 0; p->coyote = 0; }
        if (p->jbuf > 0) {
            if (p->ground || p->coyote > 0) {
                p->vy = -JUMP_V; p->ground = 0; p->coyote = 0; p->jbuf = 0; p->jumps = 1;
                add_fx(SB_FX_DUST, SN_FX_DUST, PX(p->x), PX(p->y) - 3, 3);
            } else if (p->jumps < 2) {
                p->vy = -JUMP2_V; p->jumps = 2; p->jbuf = 0; p->flip_t = 16;
                add_fx(SB_FX_DUST, SN_FX_DUST, PX(p->x), PX(p->y) - 2, 3);
            }
        }
        if (!(k & K_U) && p->vy < -48 && p->jumps == 1) p->vy = -48;
    }

    /* ---- gravite + deplacement */
    p->vy = imin(p->vy + GRAV, MAXFALL);
    int was_air = !p->ground, vy_before = (int)p->vy;
    int fl = move_box(&p->x, &p->y, &p->vx, &p->vy, P_W, P_H, p->drop_t > 0);
    p->ground = (fl & MB_GROUND) != 0;
    if (p->ground && was_air && vy_before > 70) add_fx(SB_FX_DUST, SN_FX_DUST, PX(p->x), PX(p->y) - 3, 3);

    /* ---- dangers (piques, liquide toxique, fosses) */
    int px = PX(p->x), py = PX(p->y);
    if (p->inv == 0 && p->st != PS_DEAD) {
        for (int ty = (py - 20) >> 4; ty <= ((py - 1) >> 4); ty++) for (int tx = (px - 5) >> 4; tx <= ((px + 4) >> 4); tx++) {
            int t = tile_at(tx, ty);
            if (t == TL_SPIKE && px + 5 > tx * TS + 2 && px - 5 < tx * TS + 14 && py > ty * TS + 6) { hurt_player(18, px, 0); G.p.vy = -90; }
            else if (t == TL_TOXIC && py > ty * TS + 3) { hurt_player(7, px, 0); G.p.vy = -70; }
        }
    }
    if (py > (LV_H + 2) * TS && p->st != PS_DEAD) {
        p->hp = (int16_t)(p->hp - p->maxhp * 35 / 100);
        if (p->hp <= 0) { p->hp = 0; p->st = PS_DEAD; p->dead_t = 0; p->vy = 0; p->y = F((LV_H + 2) * TS); }
        else { player_respawn_room(); msg("CHUTE !"); G.shake = 6; }
    }
    if (p->st != PS_DEAD && !G.boss_alive && tile_at(px >> 4, (py - 1) >> 4) == TL_DOOR) { if (G.passage) leave_passage(); else zone_clear(); }
}

void hurt_player(int dmg, int from_x, int kb) {
    Player *p = &G.p;
    if (p->inv > 0 || p->st == PS_DEAD || G.scene != SC_PLAY || G.passage) return;
    int blocked = 0, front = ((from_x - PX(p->x)) * p->dir) >= -3;
    if (p->guard && front && p->st == PS_NORMAL) {
        if (p->guard_t <= 8) {                                     /* PARADE parfaite : aucun degat, l'attaquant est etourdi */
            if (g_src && g_src->type < ET_GOB) { g_src->st = ES_HURT; g_src->t = 50; g_src->hit = 0; g_src->vx = 0; }
            p->inv = 14; G.hitstop = 5; G.shake = 4;
            burst(PX(p->x) + p->dir * 8, PX(p->y) - 12, 10, 2); add_fx(SB_FX_HIT, SN_FX_HIT, PX(p->x) + p->dir * 8, PX(p->y) - 12, 2);
            msg("PARADE !");
            return;
        }
        dmg = dmg * 20 / 100; kb /= 2; blocked = 1;                /* garde : 80 % des degats absorbes */
    }
    if (G.sv.opt_easy) dmg = dmg * 65 / 100;
    if (has_mut(MU_CARAPACE)) dmg = dmg * 80 / 100;
    if (dmg < 1) dmg = 1;
    p->hp = (int16_t)(p->hp - dmg); p->atk_t = 0; p->hold = 0; p->buf_atk = 0; p->combo = 0;
    if (has_mut(MU_REVENGE)) p->mt_veng = 90;
    int d = (PX(p->x) >= from_x) ? 1 : -1;
    G.shake = 6;
    add_num(PX(p->x), PX(p->y) - 24, dmg, 1); burst(PX(p->x), PX(p->y) - 12, 7, 1);
    if (blocked && p->hp > 0) { p->inv = 14; p->vx = d * kb * 16; add_fx(SB_FX_HIT, SN_FX_HIT, PX(p->x) + p->dir * 8, PX(p->y) - 12, 2); return; }
    p->inv = 36; G.hitstop = 4; p->vx = d * kb * 16; if (kb) p->vy = -60;
    add_fx(SB_FX_HIT, SN_FX_HIT, PX(p->x), PX(p->y) - 12, 2);
    if (p->hp <= 0) { p->hp = 0; p->st = PS_DEAD; p->dead_t = 0; p->vy = -80; p->vx = d * 30; }
    else { p->st = PS_HURT; p->t = 10; }
}

/* ================================================================= arene de boss */
int boss_trigger_check(void) {
    if (G.arena_x0 < 0 || G.arena_on || G.boss_idx < 0 || !G.en[G.boss_idx].alive) return 0;
    if (PX(G.p.x) > G.arena_x0 + 4 * TS) {
        G.arena_on = 1; G.boss_alive = 1;
        for (int y = 2; y <= 12; y++) G.map[y][G.arena_x0 / TS] = TL_GATE;
        Ent *b = &G.en[G.boss_idx]; b->st = ES_IDLE; b->t = 70;
        banner(b->type == ET_GOB ? "LE GOBEUR" : "LE ROI F" ECI "L" EAC, 110);
        G.shake = 8;
        return 1;
    }
    return 0;
}

/* ================================================================= deroulement d'une partie */
static void mut_offer(void) {
    int cand[MU_COUNT], c = 0;
    for (int m = 0; m < MU_COUNT; m++) if (!has_mut(m)) cand[c++] = m;
    for (int i = 0; i < 3; i++) {
        if (c == 0) { G.mut_off[i] = 255; continue; }
        int j = rn(c); G.mut_off[i] = (uint8_t)cand[j]; cand[j] = cand[--c];
    }
}

static void bank_run(void) {                  /* a l'entree d'un passage : cellules et schemas portes sont mis en lieu sur */
    G.sv.cells += (uint32_t)G.cells_run; G.cells_run = 0;
    G.sv.found |= G.bp_carry; G.bp_carry = 0;
    if (G.zone + 2 > G.sv.best_zone) G.sv.best_zone = (uint8_t)(G.zone + 2);
    save_store();
}

static void zone_clear(void) {
    Player *p = &G.p;
    if (G.zone + 1 >= NZONES) { run_end(1); return; }
    int hp = p->hp, fl = p->flasks;
    bank_run();
    build_passage(G.zone);
    p->hp = (int16_t)imin(p->maxhp, hp + p->maxhp * 30 / 100); p->flasks = (uint8_t)imin(p->maxflasks, fl + 1);
    G.mut_pending = (uint8_t)(G.mut_n < 4); G.reroll_n = 0;
    if (G.mut_pending) mut_offer();
    msg("CELLULES SAUVEGARD" EAC "ES");
}

static void leave_passage(void) {
    Player *p = &G.p;
    int hp = p->hp, fl = p->flasks, nz = G.zone + 1;
    level_build(nz);
    p->hp = (int16_t)hp; p->flasks = (uint8_t)fl;
}

static void run_end(int win) {
    int carried = (int)G.cells_run, keep = win ? carried : carried * 30 / 100;
    G.bank_gain = keep; G.bank_lost = carried - keep;
    G.sv.cells += (uint32_t)keep; G.cells_run = 0;
    if (win) G.sv.found |= G.bp_carry;
    G.bp_carry = 0;
    G.sv.runs++; if (win) G.sv.wins++; else G.sv.deaths++;
    G.sv.kills += (uint32_t)G.run_kills;
    if (G.zone + 1 > G.sv.best_zone) G.sv.best_zone = (uint8_t)(G.zone + 1);
    save_store();
    G.scene = win ? SC_WIN : SC_DEAD; G.menu_sel = 0; G.win_t = 0; G.in_run = 0;
    G.victory = (uint8_t)win;
}

static void run_start(void) {
    Player *p = &G.p;
    memset(p, 0, sizeof *p);
    p->maxhp = (int16_t)(100 + 10 * G.sv.up[UP_HP]); p->hp = p->maxhp;
    p->maxflasks = (uint8_t)(2 + G.sv.up[UP_FLASK]); p->flasks = p->maxflasks; p->dir = 1;
    G.run_gold = 0; G.run_kills = 0; G.cells_run = 0; G.bp_carry = 0; G.run_time = 0; G.victory = 0; G.shake = G.hitstop = 0;
    G.mut_n = 0; G.mut_pending = 0; G.in_run = 1; G.zone = 0;
    {   /* armes de depart au hasard parmi celles debloquees grace aux schemas */
        int melee[5] = { WP_SWORD, WP_DAGGER, WP_RAPIER, WP_HAMMER, WP_SCYTHE }, pool[5], n = 0;
        for (int i = 0; i < 5; i++) if ((G.sv.unlocked >> melee[i]) & 1) pool[n++] = melee[i];
        int a = pool[rn(n)];
        item_make(&p->w[0], a, 0, -1);
        if (a == WP_SCYTHE) p->w[1] = p->w[0];
        else {
            int b; do { b = random_weapon(a, -1); } while (b == WP_SCYTHE && n > 1 && rn(4));
            if (b == WP_SCYTHE) b = (a == WP_SWORD) ? WP_DAGGER : WP_SWORD;
            item_make(&p->w[1], b, 0, -1);
        }
    }
    level_build(0);
    G.scene = SC_PLAY;
}

/* ================================================================= boutique du Passeur (cellules) */
int shop_rows(uint8_t *kind, uint8_t *arg) {
    int n = 0;
    for (int u = 0; u < UP_COUNT; u++) { kind[n] = RW_UP; arg[n++] = (uint8_t)u; }
    for (int w = 0; w < WP_COUNT; w++) if (((G.sv.found >> w) & 1) && !((G.sv.unlocked >> w) & 1)) { kind[n] = RW_BP; arg[n++] = (uint8_t)w; }
    if (G.in_run) { kind[n] = RW_WLVL; arg[n++] = 0; kind[n] = RW_WQ; arg[n++] = 0; }
    kind[n] = RW_BACK; arg[n++] = 0;
    return n;
}
int shop_price(int kind, int arg, int *gold) {
    const Item *it = &G.p.w[G.p.cur];
    *gold = 0;
    switch (kind) {
        case RW_UP: return G.sv.up[arg] >= UP_MAX[arg] ? -1 : UP_COST[arg][G.sv.up[arg]];
        case RW_BP: return BP_COST[arg];
        case RW_WLVL: *gold = 1; return it->lvl >= 15 ? -1 : 20 + 12 * it->lvl;
        case RW_WQ: *gold = 1; return it->q >= 3 ? -1 : 50 + 40 * it->q;
        default: return -1;
    }
}

static void nav(int n) {
    if (G.pressed & K_U) G.menu_sel = (int16_t)((G.menu_sel + n - 1) % n);
    if (G.pressed & K_D) G.menu_sel = (int16_t)((G.menu_sel + 1) % n);
}

static void leave_shop(void) {
    G.scene = G.in_run ? SC_PLAY : SC_TITLE; G.menu_sel = 1;
}

static void shop_update(void) {
    uint8_t k[24], a[24];
    int n = shop_rows(k, a);
    if (G.menu_sel >= n) G.menu_sel = (int16_t)(n - 1);
    nav(n);
    if (G.msg_t > 0) G.msg_t--;
    if (G.pressed & K_BACK) { leave_shop(); return; }
    if (!(G.pressed & K_OK)) return;
    int s = G.menu_sel, gold;
    if (k[s] == RW_BACK) { leave_shop(); return; }
    int price = shop_price(k[s], a[s], &gold);
    if (price < 0) { msg("AU MAXIMUM"); return; }
    if (gold ? G.run_gold < price : G.sv.cells < (uint32_t)price) { msg(gold ? "PAS ASSEZ DE PI" EGR "CES" : "PAS ASSEZ DE CELLULES"); return; }
    if (gold) G.run_gold -= price; else G.sv.cells -= (uint32_t)price;
    Player *p = &G.p;
    switch (k[s]) {
        case RW_UP:
            G.sv.up[a[s]]++;
            if (G.in_run && a[s] == UP_HP) { p->maxhp += 10; p->hp += 10; }
            if (G.in_run && a[s] == UP_FLASK) { p->maxflasks++; p->flasks++; }
            break;
        case RW_BP: G.sv.unlocked |= (uint16_t)(1 << a[s]); msg("ARME D" EAC "BLOQU" EAC "E"); break;
        case RW_WLVL: p->w[p->cur].lvl++; break;
        default: p->w[p->cur].q++; break;
    }
    if (p->w[p->cur].id == WP_SCYTHE) p->w[p->cur ^ 1] = p->w[p->cur];
    save_store();
}

/* ================================================================= mutations de l'Oracle (valables pour la partie seulement) */
static void mut_update(void) {
    int n = G.mut_pending ? 5 : 1;
    if (G.menu_sel >= n) G.menu_sel = (int16_t)(n - 1);
    nav(n);
    if (G.msg_t > 0) G.msg_t--;
    if (G.pressed & K_BACK) { G.scene = SC_PLAY; return; }
    if (!(G.pressed & K_OK)) return;
    int s = G.menu_sel;
    if (!G.mut_pending || s == 4) { G.scene = SC_PLAY; return; }
    if (s == 3) {                                                                         /* relancer le tirage contre des pieces */
        int cost = 40 * (G.reroll_n + 1);
        if (G.run_gold < cost) { msg("PAS ASSEZ DE PI" EGR "CES"); return; }
        G.run_gold -= cost; G.reroll_n++; mut_offer(); return;
    }
    if (G.mut_off[s] == 255) return;
    G.mut[G.mut_n++] = G.mut_off[s]; G.mut_pending = 0;
    if (G.mut_off[s] == MU_GLUTTON) { G.p.maxflasks++; G.p.flasks++; }
    msg(MU_NAME[G.mut_off[s]]);
    G.scene = SC_PLAY;
}

/* ================================================================= scenes */
static void cam_update(void) {
    int target;
    if (G.arena_on) target = G.arena_x0; else target = PX(G.p.x) - 160 + G.p.dir * 28;
    target = imax(0, imin(target, G.lvw * TS - SCR_W));
    G.cam_x += (F(target) - G.cam_x) / 5;
}

static void play_update(void) {
    if (G.pressed & K_PAUSE) { G.scene = SC_PAUSE; G.menu_sel = 0; return; }
    if (G.hitstop > 0) { G.hitstop--; return; }
    G.run_time++;
    player_update();
    if (G.scene != SC_PLAY) return;
    boss_trigger_check();
    ai_update();
    cam_update();
    if (G.banner_t > 0) G.banner_t--;
    if (G.msg_t > 0) G.msg_t--;
    if (G.hint_t > 0) G.hint_t--;
    if (G.shake > 0) G.shake--;
    if (G.p.st == PS_DEAD && G.p.dead_t > 70) run_end(0);
    else if (G.victory && G.scene == SC_PLAY && ++G.win_t > 110) run_end(1);
}

static void title_update(void) {
    nav(5);
    if (G.pressed & K_OK) {
        switch (G.menu_sel) {
            case 0: run_start(); break;
            case 1: G.in_run = 0; G.scene = SC_SHOP; G.menu_sel = 0; break;
            case 2: G.scene = SC_OPTIONS; G.menu_sel = 0; G.menu_sub = 0; break;
            case 3: G.scene = SC_HELP; break;
            default: G.quit = 1; break;
        }
    }
}

static void options_update(void) {
    nav(4);
    if (G.msg_t > 0) G.msg_t--;
    if (G.pressed & K_BACK) { G.scene = SC_TITLE; G.menu_sel = 2; return; }
    if (G.pressed & (K_OK | K_L | K_R)) {
        switch (G.menu_sel) {
            case 0: G.sv.opt_fx ^= 1; save_store(); break;
            case 1: G.sv.opt_easy ^= 1; save_store(); break;
            case 2:
                if (G.pressed & K_OK) {
                    if (G.menu_sub) { save_defaults(); save_store(); G.menu_sub = 0; msg("PROGRESSION EFFAC" EAC "E"); } else G.menu_sub = 1;
                }
                break;
            default: if (G.pressed & K_OK) { G.scene = SC_TITLE; G.menu_sel = 2; } break;
        }
    }
    if (G.menu_sel != 2) G.menu_sub = 0;
}

void game_update(uint16_t keys) {
    G.prev = G.keys; G.keys = keys; G.pressed = (uint16_t)(keys & ~G.prev); G.frame++;
    switch (G.scene) {
        case SC_TITLE: title_update(); break;
        case SC_PLAY: play_update(); break;
        case SC_PAUSE:
            nav(3);
            if (G.pressed & (K_PAUSE | K_BACK)) { G.scene = SC_PLAY; break; }
            if (G.pressed & K_OK) {
                if (G.menu_sel == 0) G.scene = SC_PLAY;
                else if (G.menu_sel == 1) { G.scene = SC_HELP; G.menu_sub = 1; }
                else { run_end(0); G.scene = SC_TITLE; G.menu_sel = 0; }
            }
            break;
        case SC_SHOP: shop_update(); break;
        case SC_MUT: mut_update(); break;
        case SC_OPTIONS: options_update(); break;
        case SC_HELP:
            if (G.pressed & (K_R | K_L)) G.help_page ^= 1;
            if (G.pressed & (K_BACK | K_OK)) { G.help_page = 0; if (G.menu_sub) { G.scene = SC_PAUSE; G.menu_sub = 0; } else { G.scene = SC_TITLE; G.menu_sel = 3; } }
            break;
        case SC_DEAD: case SC_WIN:
            G.win_t++;
            part_update();
            if (G.pressed & K_OK) { G.in_run = 0; G.scene = SC_SHOP; G.menu_sel = 0; }
            if (G.pressed & K_BACK) { G.scene = SC_TITLE; G.menu_sel = 0; }
            break;
        default: break;
    }
}

void game_init(uint32_t seed) {
    memset(&G, 0, sizeof G);
    G.rng = seed ? seed : 0x1234567u;
    save_load();
    G.scene = SC_TITLE; G.menu_sel = 0;
}
int game_quit_requested(void) { return G.quit; }

/* ======== dc_ai.c ======== */
/* dc_ai.c - ennemis (melee, distance, rapide, resistant, lanceur de bombes, garde-bouclier, zombie toxique, volant),
   elites, 2 boss, projectiles, objets (pieces, cellules, schemas, armes), particules. */

typedef struct { uint8_t w, h; int16_t hp; uint8_t dmg, coins; } EDef;
static const EDef ED[ET_COUNT] = {
    {12, 22, 36, 12, 3},      /* ET_JAIL  : melee                         */
    {12, 22, 24, 10, 3},      /* ET_XBOW  : a distance                    */
    {14, 10, 14, 6, 1},       /* ET_RAT   : rapide                        */
    {20, 28, 90, 22, 8},      /* ET_BRUTE : resistant                     */
    {14, 12, 28, 8, 2},       /* ET_SLIME : egouts                        */
    {12, 22, 30, 18, 4},      /* ET_GREN  : artificier (bombes en cloche) */
    {14, 24, 55, 14, 5},      /* ET_SHLD  : garde-bouclier (garde frontale)*/
    {12, 22, 48, 10, 3},      /* ET_TOXIC : putride (nuage a sa mort)      */
    {14, 10, 14, 8, 1},       /* ET_BAT   : volant, pique sur le joueur    */
    {34, 30, 260, 14, 60},    /* ET_GOB   : boss des egouts               */
    {24, 46, 380, 22, 120},   /* ET_KING  : boss final                    */
};
int ent_w(const Ent *e) { return ED[e->type].w; }
int ent_h(const Ent *e) { return ED[e->type].h; }
int enemy_hp_scale(int base, int zone) { return base * (100 + 22 * zone) / 100; }
static int edmg(const Ent *e) { return ED[e->type].dmg * (100 + 10 * G.zone) / 100 * (e->elite ? 125 : 100) / 100; }


#define GRAV 9
#define MAXFALL 140

static int pdx(const Ent *e) { return PX(G.p.x) - PX(e->x); }
static int pdy(const Ent *e) { return (PX(G.p.y) - 10) - (PX(e->y) - ED[e->type].h / 2); }
static void face(Ent *e) { e->dir = (int8_t)((pdx(e) >= 0) ? 1 : -1); }
static int ground_ahead(const Ent *e, int dir, int dist) {
    int x = PX(e->x) + dir * (ED[e->type].w / 2 + dist + 1), t = tile_at(x >> 4, PX(e->y) >> 4);
    return is_solid(t) || t == TL_PLAT;
}
static int wall_ahead(const Ent *e, int dir) {
    int x = PX(e->x) + dir * (ED[e->type].w / 2 + 1);
    return is_solid(tile_at(x >> 4, (PX(e->y) - 4) >> 4));
}
static int touch(const Ent *e) {
    return player_box_overlap(PX(e->x) - ED[e->type].w / 2, PX(e->y) - ED[e->type].h, ED[e->type].w, ED[e->type].h);
}
static void en_phys(Ent *e) {
    e->vy = imin(e->vy + GRAV, MAXFALL);
    int fl = move_box(&e->x, &e->y, &e->vx, &e->vy, ED[e->type].w, ED[e->type].h, 0);
    e->ground = (fl & MB_GROUND) != 0;
    if (PX(e->y) > (LV_H + 3) * TS) e->alive = 0;
}

/* ================================================================= creation / objets */
void add_proj(int type, int owner, int x, int y, int vx, int vy, int dmg, int life, int dir) {
    for (int i = 0; i < MAX_PR; i++) if (G.pr[i].life == 0) {
        Proj *p = &G.pr[i];
        memset(p, 0, sizeof *p);
        p->x = F(x); p->y = F(y); p->vx = vx; p->vy = vy; p->dmg = (int16_t)dmg; p->life = (int16_t)life;
        p->type = (uint8_t)type; p->owner = (uint8_t)owner; p->dir = (int8_t)dir;
        p->pierce = (type == PJ_PARROW) ? 2 : 0;
        return;
    }
}
static Pick *new_pick(void) {
    for (int i = 0; i < MAX_PK; i++) if (G.pk[i].life == 0) { memset(&G.pk[i], 0, sizeof(Pick)); G.pk[i].life = 255; return &G.pk[i]; }
    return 0;
}
void add_pick(int kind, int x, int y, int val, int vx, int vy) {
    Pick *k = new_pick();
    if (!k) return;
    k->x = F(x); k->y = F(y); k->vx = vx; k->vy = vy; k->kind = (uint8_t)kind; k->val = (uint8_t)val;
}
void add_item_pick(int x, int y, const Item *it, int vy) {
    Pick *k = new_pick();
    if (!k) return;
    k->x = F(x); k->y = F(y); k->vy = vy; k->kind = PK_WPN; k->val = it->id; k->lvl = it->lvl; k->q = it->q;
}
void spawn_coins(int x, int y, int total) {
    int n = imin(total, 8), base, rem;
    if (n <= 0) return;
    base = total / n; rem = total % n;
    for (int i = 0; i < n; i++) add_pick(PK_COIN, x, y, base + (i < rem), rn(61) - 30, -(40 + rn(50)));
}
void spawn_cells(int x, int y, int n) {
    for (int i = 0; i < imin(n, 8); i++) add_pick(PK_CELL, x, y, 1, rn(61) - 30, -(50 + rn(50)));
}
void drop_blueprint(int x, int y) {            /* schema d'une arme encore verrouillee et pas deja trouvee */
    int cand[WP_COUNT], c = 0;
    for (int w = 0; w < WP_COUNT; w++) if (!((G.sv.unlocked >> w) & 1) && !((G.sv.found >> w) & 1) && !((G.bp_carry >> w) & 1)) cand[c++] = w;
    if (c) add_pick(PK_BLUE, x, y, cand[rn(c)], rn(31) - 15, -70);
}
void spawn_enemy(int type, int tx, int ty, int zone) {
    for (int i = 0; i < MAX_EN; i++) if (!G.en[i].alive) {
        Ent *e = &G.en[i];
        memset(e, 0, sizeof *e);
        e->type = (uint8_t)type; e->alive = 1;
        e->x = F(tx * TS + 8); e->y = F((ty + 1) * TS);
        e->hp = e->maxhp = (int16_t)enemy_hp_scale(ED[type].hp, zone);
        e->dir = (int8_t)(rn(2) ? 1 : -1); e->st = ES_PATROL; e->home = (int16_t)(tx * TS + 8);
        e->skin = (uint8_t)(type < ET_GOB ? zone : 0); e->cd = (int16_t)(30 + rn(40));
        if (type == ET_SLIME) e->st = ES_CHASE;
        if (type < ET_GOB && rn(100) < 5 + zone) { e->elite = 1; e->hp = e->maxhp = (int16_t)(e->maxhp * 22 / 10); }
        return;
    }
}

static void kill_enemy(Ent *e) {
    int boss = (e->type >= ET_GOB), x = PX(e->x), y = PX(e->y), cy = y - ED[e->type].h / 2;
    int loot = 100 + 10 * G.sv.up[UP_LOOT] + (has_mut(MU_LUCK) ? 25 : 0);
    e->st = ES_DEAD; e->t = 0; e->hit = 0; e->vy = -50; e->vx = 0; e->burn = 0;
    G.run_kills++;
    on_kill_hooks();
    spawn_coins(x, cy, ED[e->type].coins * (e->elite ? 2 : 1) * loot / 100);
    burst(x, cy, boss ? 24 : 8, 0);
    if (e->type == ET_TOXIC) add_proj(PJ_CLOUD, 1, x, y - 6, 0, 0, 5, 150, 1);       /* nuage de poison a la mort */
    if (!boss) {
        int r = rn(100), cell_ch = (e->type == ET_BRUTE || e->type == ET_GREN || e->type == ET_SHLD) ? 35 : 22;
        if (e->elite) { spawn_cells(x, cy, 3 + rn(3)); if (rn(100) < 30) drop_blueprint(x, cy); }
        else if (rn(100) < cell_ch * loot / 100) spawn_cells(x, cy, 1);
        if (r < 12) add_pick(PK_HEART, x, y - 10, 0, 0, -50);
        else if (r < 16) add_pick(PK_FLASK, x, y - 10, 0, 0, -50);
        return;
    }
    G.boss_alive = 0; G.shake = 14;
    if (G.arena_x0 >= 0) for (int ty = 2; ty <= 12; ty++) G.map[ty][G.arena_x0 / TS] = TL_EMPTY;
    if (G.door_tx >= 0) G.map[G.door_ty][G.door_tx] = TL_DOOR;
    spawn_cells(x, cy, e->type == ET_GOB ? 8 : 8);
    spawn_cells(x, cy, e->type == ET_GOB ? 0 : 7);
    drop_blueprint(x, cy);
    if (e->type == ET_GOB) {                                    /* arme legendaire (qualite L) */
        Item it;
        item_make(&it, random_weapon(G.p.w[0].id, G.p.w[1].id), 2, 4);
        add_item_pick(x, y - 24, &it, -70);
        banner("BOSS VAINCU", 100);
    } else { G.victory = 1; G.win_t = 0; banner("VICTOIRE !", 140); }
}

void hurt_enemy(Ent *e, int dmg, int dir, int kb, int stun) {
    if (!e->alive || e->st == ES_DEAD || e->st == ES_SLEEP) return;
    int boss = (e->type >= ET_GOB), cy = PX(e->y) - ED[e->type].h / 2;
    if (e->type == ET_SHLD && !g_pierce && dir == -e->dir && (e->st == ES_PATROL || e->st == ES_CHASE || e->st == ES_ATK)) {
        if (stun >= 12) {                                       /* coup lourd : la garde est brisee */
            e->st = ES_HURT; e->t = 50; e->hit = 0; dmg = dmg * 6 / 10; kb = 0;
            add_fx(SB_FX_HIT, SN_FX_HIT, PX(e->x) + dir * -8, cy, 2);
        } else {                                                /* coup leger : bloque par le bouclier */
            burst(PX(e->x) - e->dir * -8, cy, 4, 2); add_fx(SB_FX_HIT, 1, PX(e->x) + (dir > 0 ? -8 : 8), cy, 2);
            e->vx += dir * 16; return;
        }
    }
    if (e->type == ET_BRUTE && stun < 12) { dmg = dmg * 70 / 100; kb = 0; stun = 0; }   /* armure : coups legers reduits */
    if (dmg < 1) dmg = 1;
    if (dmg > 9999) dmg = 9999;                                   /* evite tout debordement des PV (int16) */
    e->hp = (int16_t)(e->hp - dmg); e->flash = 4;
    add_num(PX(e->x), PX(e->y) - ED[e->type].h - 4, dmg, g_crit ? 4 : 2);
    burst(PX(e->x), cy, 4, 0);
    add_fx(SB_FX_HIT, SN_FX_HIT, PX(e->x) - dir * 4, cy, 2);
    if (e->hp <= 0) { kill_enemy(e); return; }
    if (!boss) {
        e->vx += dir * kb * 16; if (kb) e->vy = -30;
        if (stun > 0 && e->st != ES_HURT) { e->st = ES_HURT; e->t = (int16_t)stun; e->hit = 0; }
    }
}

/* ================================================================= ennemis simples */
static void patrol_turn(Ent *e, int speed, int range) {
    e->vx = e->dir * speed;
    if (!ground_ahead(e, e->dir, 2) || wall_ahead(e, e->dir) || iabs(PX(e->x) - e->home) > range) { e->dir = (int8_t)-e->dir; e->vx = e->dir * speed; }
}

static void en_jail(Ent *e) {
    int adx = iabs(pdx(e)), dy = iabs(pdy(e)), near_ = adx < 130 && dy < 44;
    switch (e->st) {
    case ES_PATROL: patrol_turn(e, 14, 72); if (near_) e->st = ES_CHASE; break;
    case ES_CHASE:
        face(e);
        if (adx > 190) { e->st = ES_PATROL; e->vx = 0; break; }
        if (adx <= 28 && dy < 28) { e->st = ES_WIND; e->t = 14; e->vx = 0; break; }
        e->vx = (ground_ahead(e, e->dir, 2) && !wall_ahead(e, e->dir)) ? e->dir * 18 : 0;
        break;
    case ES_WIND: e->vx = 0; if (--e->t <= 0) { e->st = ES_ATK; e->t = 5; e->hit = 0; } break;
    case ES_ATK: {
        int x0 = (e->dir > 0) ? PX(e->x) + 2 : PX(e->x) - 28;
        e->vx = 0;
        if (!e->hit && player_box_overlap(x0, PX(e->y) - 24, 26, 22)) { hurt_player(edmg(e), PX(e->x), 3); e->hit = 1; }
        if (--e->t <= 0) { e->st = ES_REC; e->t = 18; }
        break; }
    case ES_REC: e->vx = 0; if (--e->t <= 0) e->st = ES_CHASE; break;
    default: break;
    }
}

static void en_xbow(Ent *e) {
    int adx = iabs(pdx(e)), dy = iabs(pdy(e)), seen = adx < 200 && dy < 60;
    if (e->cd > 0) e->cd--;
    switch (e->st) {
    case ES_PATROL: patrol_turn(e, 10, 60); if (seen) e->st = ES_CHASE; break;
    case ES_CHASE:
        face(e);
        if (adx > 270) { e->st = ES_PATROL; e->vx = 0; break; }
        if (adx < 70 && ground_ahead(e, -e->dir, 2) && !wall_ahead(e, -e->dir)) e->vx = -e->dir * 14;
        else if (adx > 150 && ground_ahead(e, e->dir, 2) && !wall_ahead(e, e->dir)) e->vx = e->dir * 10;
        else e->vx = 0;
        if (e->cd <= 0 && seen) { e->st = ES_WIND; e->t = 18; e->vx = 0; }
        break;
    case ES_WIND:
        e->vx = 0; face(e);
        if (--e->t <= 0) {
            add_proj(PJ_BOLT, 1, PX(e->x) + e->dir * 12, PX(e->y) - 14, e->dir * 72, 0, edmg(e), 90, e->dir);
            e->st = ES_REC; e->t = 14; e->cd = (int16_t)(50 + rn(30));
        }
        break;
    case ES_REC: e->vx = 0; if (--e->t <= 0) e->st = ES_CHASE; break;
    default: break;
    }
}

static void en_rat(Ent *e) {
    int adx = iabs(pdx(e)), dy = iabs(pdy(e));
    switch (e->st) {
    case ES_PATROL:
        patrol_turn(e, 12, 80);
        if (adx < 130 && dy < 40) { face(e); e->st = ES_WIND; e->t = 10; e->vx = 0; }
        break;
    case ES_WIND: e->vx = 0; if (--e->t <= 0) { e->st = ES_ATK; e->t = 36; e->hit = 0; } break;
    case ES_ATK:
        e->vx = e->dir * 50;
        if (wall_ahead(e, e->dir) || !ground_ahead(e, e->dir, 0)) { e->vx = 0; e->t = 1; }
        if (!e->hit && touch(e)) { hurt_player(edmg(e), PX(e->x), 3); e->hit = 1; }
        if (--e->t <= 0) { e->st = ES_REC; e->t = 26; e->vx = 0; }
        break;
    case ES_REC: e->vx = 0; if (--e->t <= 0) e->st = ES_PATROL; break;
    default: break;
    }
}

static void en_brute(Ent *e) {
    int adx = iabs(pdx(e)), dy = iabs(pdy(e));
    switch (e->st) {
    case ES_PATROL: patrol_turn(e, 8, 60); if (adx < 120 && dy < 48) e->st = ES_CHASE; break;
    case ES_CHASE:
        face(e);
        if (adx > 200) { e->st = ES_PATROL; e->vx = 0; break; }
        if (adx < 40 && dy < 34) { e->st = ES_WIND; e->t = 24; e->vx = 0; break; }
        e->vx = (ground_ahead(e, e->dir, 2) && !wall_ahead(e, e->dir)) ? e->dir * 9 : 0;
        break;
    case ES_WIND: e->vx = 0; if (--e->t <= 0) { e->st = ES_ATK; e->t = 6; e->hit = 0; add_fx(SB_FX_SMASH, SN_FX_SMASH, PX(e->x) + e->dir * 26, PX(e->y) - 8, 3); } break;
    case ES_ATK: {
        int x0 = (e->dir > 0) ? PX(e->x) + 2 : PX(e->x) - 40;
        e->vx = 0;
        if (!e->hit && player_box_overlap(x0, PX(e->y) - 28, 38, 28)) { hurt_player(edmg(e), PX(e->x), 5); e->hit = 1; }
        if (--e->t <= 0) { e->st = ES_REC; e->t = 32; }
        break; }
    case ES_REC: e->vx = 0; if (--e->t <= 0) e->st = ES_CHASE; break;
    default: break;
    }
}

static void en_slime(Ent *e) {
    int adx = iabs(pdx(e));
    if (e->st == ES_AIR) {
        if (e->ground) { e->st = ES_CHASE; e->vx = 0; e->cd = (int16_t)(30 + rn(30)); }
    } else {
        e->vx = 0;
        if (e->cd > 0) e->cd--;
        if (e->cd <= 0 && adx < 170) { face(e); e->vy = -95; e->vx = e->dir * 28; e->st = ES_AIR; e->ground = 0; }
    }
    if (touch(e)) hurt_player(edmg(e), PX(e->x), 3);
}

/* ---- artificier : garde ses distances et lance des bombes en cloche */
static void en_gren(Ent *e) {
    int dx = pdx(e), adx = iabs(dx), dy = iabs(pdy(e)), seen = adx < 210 && dy < 90;
    if (e->cd > 0) e->cd--;
    switch (e->st) {
    case ES_PATROL: patrol_turn(e, 10, 60); if (seen) e->st = ES_CHASE; break;
    case ES_CHASE:
        face(e);
        if (adx > 280) { e->st = ES_PATROL; e->vx = 0; break; }
        if (adx < 80 && ground_ahead(e, -e->dir, 2) && !wall_ahead(e, -e->dir)) e->vx = -e->dir * 14;
        else if (adx > 170 && ground_ahead(e, e->dir, 2) && !wall_ahead(e, e->dir)) e->vx = e->dir * 11;
        else e->vx = 0;
        if (e->cd <= 0 && seen) { e->st = ES_WIND; e->t = 20; e->vx = 0; }
        break;
    case ES_WIND:
        e->vx = 0; face(e);
        if (--e->t <= 0) {
            add_proj(PJ_BOMB, 1, PX(e->x) + e->dir * 8, PX(e->y) - 24, clampi(pdx(e) / 2, -80, 80), -96, edmg(e), 120, e->dir);
            e->st = ES_REC; e->t = 14; e->cd = (int16_t)(70 + rn(40));
        }
        break;
    case ES_REC: e->vx = 0; if (--e->t <= 0) e->st = ES_CHASE; break;
    default: break;
    }
}

/* ---- garde-bouclier : garde frontale (voir hurt_enemy) ; vulnerable quand il prepare son coup de bouclier */
static void en_shld(Ent *e) {
    int adx = iabs(pdx(e)), dy = iabs(pdy(e));
    switch (e->st) {
    case ES_PATROL: patrol_turn(e, 8, 56); if (adx < 140 && dy < 48) e->st = ES_CHASE; break;
    case ES_CHASE:
        face(e);
        if (adx > 220) { e->st = ES_PATROL; e->vx = 0; break; }
        if (adx < 36 && dy < 30) { e->st = ES_WIND; e->t = 16; e->vx = 0; break; }
        e->vx = (ground_ahead(e, e->dir, 2) && !wall_ahead(e, e->dir)) ? e->dir * 12 : 0;
        break;
    case ES_WIND: e->vx = 0; if (--e->t <= 0) { e->st = ES_ATK; e->t = 6; e->hit = 0; } break;
    case ES_ATK: {
        int x0 = (e->dir > 0) ? PX(e->x) + 2 : PX(e->x) - 26;
        e->vx = e->dir * 20;
        if (wall_ahead(e, e->dir) || !ground_ahead(e, e->dir, 0)) e->vx = 0;
        if (!e->hit && player_box_overlap(x0, PX(e->y) - 24, 24, 22)) { hurt_player(edmg(e), PX(e->x), 5); e->hit = 1; }
        if (--e->t <= 0) { e->st = ES_REC; e->t = 22; }
        break; }
    case ES_REC: e->vx = 0; if (--e->t <= 0) e->st = ES_CHASE; break;
    default: break;
    }
}

/* ---- putride : zombie toxique, lent, laisse un nuage de poison en mourant */
static void en_toxic(Ent *e) {
    int adx = iabs(pdx(e)), dy = iabs(pdy(e));
    switch (e->st) {
    case ES_PATROL: patrol_turn(e, 7, 50); if (adx < 120 && dy < 44) e->st = ES_CHASE; break;
    case ES_CHASE:
        face(e);
        if (adx > 200) { e->st = ES_PATROL; e->vx = 0; break; }
        if (adx <= 26 && dy < 30) { e->st = ES_WIND; e->t = 16; e->vx = 0; break; }
        e->vx = (ground_ahead(e, e->dir, 2) && !wall_ahead(e, e->dir)) ? e->dir * 11 : 0;
        break;
    case ES_WIND: e->vx = 0; if (--e->t <= 0) { e->st = ES_ATK; e->t = 5; e->hit = 0; } break;
    case ES_ATK: {
        int x0 = (e->dir > 0) ? PX(e->x) + 2 : PX(e->x) - 30;
        e->vx = 0;
        if (!e->hit && player_box_overlap(x0, PX(e->y) - 22, 28, 20)) { hurt_player(edmg(e), PX(e->x), 3); e->hit = 1; }
        if (--e->t <= 0) { e->st = ES_REC; e->t = 20; }
        break; }
    case ES_REC: e->vx = 0; if (--e->t <= 0) e->st = ES_CHASE; break;
    default: break;
    }
}

/* ---- volant : plane au-dessus du joueur puis pique */
static void bat_move(Ent *e) {
    int32_t nx = e->x + e->vx, ny;
    if (is_solid(tile_at(PX(nx) >> 4, (PX(e->y) - 5) >> 4))) { e->vx = 0; if (e->st == ES_ATK) { e->st = ES_REC; e->t = 20; } else e->dir = (int8_t)-e->dir; }
    else e->x = nx;
    ny = e->y + e->vy;
    if (is_solid(tile_at(PX(e->x) >> 4, (PX(ny) - 5) >> 4)) || PX(ny) < 3 * TS) { e->vy = 0; if (e->st == ES_ATK) { e->st = ES_REC; e->t = 20; } }
    else e->y = ny;
    if (PX(e->y) > 13 * TS) { e->y = F(13 * TS); e->vy = 0; if (e->st == ES_ATK) { e->st = ES_REC; e->t = 20; } }
}
static void en_bat(Ent *e) {
    int dx = pdx(e), adx = iabs(dx), ty = imax(3 * TS + 10, PX(G.p.y) - 52);
    switch (e->st) {
    case ES_PATROL:
        e->vx = e->dir * 8; e->vy = (e->anim & 32) ? 4 : -4;
        if (adx < 170 && iabs(pdy(e)) < 150) e->st = ES_CHASE;
        break;
    case ES_CHASE:
        face(e);
        e->vx = (adx > 16) ? ((dx > 0) ? 18 : -18) : 0;
        e->vy = clampi((ty - PX(e->y)) * 2, -16, 16);
        if (e->cd > 0) e->cd--;
        if (e->cd <= 0 && adx < 90) { e->st = ES_WIND; e->t = 12; e->vx = e->vy = 0; }
        if (adx > 300) e->st = ES_PATROL;
        break;
    case ES_WIND:
        face(e); e->vx = e->vy = 0;
        if (--e->t <= 0) {
            int ddx = PX(G.p.x) - PX(e->x), ddy = (PX(G.p.y) - 10) - (PX(e->y) - 5), n = imax(1, imax(iabs(ddx), iabs(ddy)));
            e->vx = ddx * 64 / n; e->vy = ddy * 64 / n; e->st = ES_ATK; e->t = 26; e->hit = 0;
        }
        break;
    case ES_ATK:
        if (!e->hit && touch(e)) { hurt_player(edmg(e), PX(e->x), 3); e->hit = 1; }
        if (e->hit || --e->t <= 0) { e->st = ES_REC; e->t = 20; }
        break;
    case ES_REC:
        e->vx = -e->dir * 10; e->vy = -20;
        if (--e->t <= 0) { e->st = ES_CHASE; e->cd = (int16_t)(50 + rn(40)); }
        break;
    default: break;
    }
    bat_move(e);
}

/* ================================================================= boss 1 : le Gobeur */
static void waves(Ent *e, int speed, int dmg, int life) {
    int x = PX(e->x), y = PX(e->y);
    add_proj(PJ_WAVE, 1, x - 14, y, -speed, 0, dmg, life, -1);
    add_proj(PJ_WAVE, 1, x + 14, y, speed, 0, dmg, life, 1);
    add_fx(SB_FX_SMASH, SN_FX_SMASH, x, y - 8, 3);
    G.shake = 8;
}

static void en_gob(Ent *e) {
    int dx = pdx(e), enr = e->hp * 100 < e->maxhp * 40;
    switch (e->st) {
    case ES_IDLE:
        e->vx = 0; face(e);
        if (--e->t <= 0) {
            int a; do { a = rn(3); } while (a == e->aux && rn(3));
            e->aux = (uint8_t)a; e->st = ES_WIND; e->t = (int16_t)(a == 1 ? 18 : 14);
        }
        break;
    case ES_WIND:
        e->vx = 0; face(e);
        if (--e->t <= 0) {
            if (e->aux == 0) { e->vy = -100; e->vx = clampi(dx * 16 / 22, -48, 48); e->st = ES_AIR; e->t = 0; e->ground = 0; }
            else if (e->aux == 1) {
                int n = enr ? 5 : 3;
                for (int k = 0; k < n; k++) add_proj(PJ_SPIT, 1, PX(e->x) + e->dir * 14, PX(e->y) - 24, e->dir * (26 + k * 11), -(50 + k * 20), edmg(e) - 3, 120, e->dir);
                e->st = ES_REC; e->t = (int16_t)(enr ? 16 : 28);
            } else { e->vy = -170; e->vx = 0; e->st = ES_AIR; e->t = 0; e->ground = 0; }
        }
        break;
    case ES_AIR:
        if (e->aux == 2) {
            if (e->t == 0) { e->vx = clampi(dx * 2, -48, 48); if (e->vy >= 0) { e->t = 1; e->vy = 130; e->vx = 0; } }
            else e->vx = 0;
        }
        if (e->ground) { waves(e, 40, edmg(e) - 2, 46); e->st = ES_REC; e->t = (int16_t)(enr ? 14 : 26); e->vx = 0; }
        break;
    case ES_REC: e->vx = 0; if (--e->t <= 0) { e->st = ES_IDLE; e->t = (int16_t)(enr ? 14 : 30 + rn(20)); } break;
    default: break;
    }
    if (e->st != ES_SLEEP && touch(e)) hurt_player(edmg(e), PX(e->x), 4);
}

/* ================================================================= boss final : le Roi Fele */
static void en_king(Ent *e) {
    int adx = iabs(pdx(e)), enr = e->hp * 2 < e->maxhp;
    switch (e->st) {
    case ES_IDLE:
        face(e);
        e->vx = (adx > 44) ? e->dir * (enr ? 20 : 15) : 0;
        if (e->cd > 0) e->cd--;
        if (e->cd <= 0) {
            int a = rn(3);
            if (a == e->aux && rn(2)) a = (a + 1) % 3;
            e->aux = (uint8_t)a; e->st = ES_WIND; e->t = (int16_t)(a == 1 ? 18 : 22); e->vx = 0; e->hit = 0;
        }
        break;
    case ES_WIND:
        e->vx = 0; if (e->aux != 0) face(e);
        if (--e->t <= 0) {
            e->st = ES_ATK; e->hit = 0; e->t = (int16_t)(e->aux == 0 ? 34 : (e->aux == 1 ? 6 : 5));
            if (e->aux == 2) {
                waves(e, 48, edmg(e) - 6, 56);
                if (enr) {
                    int rats = 0;
                    for (int i = 0; i < MAX_EN; i++) if (G.en[i].alive && G.en[i].type == ET_RAT) rats++;
                    for (; rats < 2 && G.arena_x0 >= 0; rats++) spawn_enemy(ET_RAT, G.arena_x0 / TS + 2 + rn(16), 12, G.zone);
                }
            }
        }
        break;
    case ES_ATK:
        if (e->aux == 0) {
            e->vx = e->dir * (enr ? 90 : 78);
            if (!e->hit && touch(e)) { hurt_player(edmg(e), PX(e->x), 6); e->hit = 1; }
            if (wall_ahead(e, e->dir)) { e->st = ES_REC; e->t = 40; e->vx = 0; G.shake = 8; burst(PX(e->x) + e->dir * 12, PX(e->y) - 20, 8, 0); }
            else if (--e->t <= 0) { e->st = ES_REC; e->t = 22; e->vx = 0; }
        } else if (e->aux == 1) {
            int x0 = (e->dir > 0) ? PX(e->x) + 4 : PX(e->x) - 62;
            e->vx = 0;
            if (!e->hit && player_box_overlap(x0, PX(e->y) - 44, 58, 44)) { hurt_player(edmg(e), PX(e->x), 5); e->hit = 1; }
            if (--e->t <= 0) { e->st = ES_REC; e->t = 18; }
        } else { e->vx = 0; if (--e->t <= 0) { e->st = ES_REC; e->t = 24; } }
        break;
    case ES_REC: e->vx = 0; if (--e->t <= 0) { e->st = ES_IDLE; e->cd = (int16_t)(enr ? 24 + rn(20) : 46 + rn(30)); } break;
    default: break;
    }
    if (e->st != ES_SLEEP && e->st != ES_ATK && touch(e)) hurt_player(edmg(e) / 2, PX(e->x), 3);
}

static void enemy_update(Ent *e) {
    if (!e->alive) return;
    e->anim++;
    if (e->flash > 0) e->flash--;
    if (e->burn > 0 && e->st != ES_DEAD && e->st != ES_SLEEP) {                 /* brulure / saignement */
        e->burn--;
        if (e->burn % 15 == 0) {
            int d = 3 + G.zone;
            e->hp = (int16_t)(e->hp - d); e->flash = 2;
            add_part(PA_EMBER, PX(e->x), PX(e->y) - ED[e->type].h, rn(21) - 10, -12, 12, 0);
            if (e->hp <= 0) kill_enemy(e);
        }
    }
    if (e->st == ES_SLEEP) { en_phys(e); return; }
    if (e->st == ES_DEAD) {
        e->t++; e->vx = e->vx * 3 / 4; en_phys(e);
        if (e->t >= (e->type >= ET_GOB ? 50 : 26)) e->alive = 0;
        return;
    }
    if (e->type < ET_GOB && iabs(pdx(e)) > 420) return;               /* trop loin : on ne simule pas */
    if (e->st == ES_HURT) {
        e->vx = e->vx * 3 / 4;
        if (--e->t <= 0) e->st = ES_CHASE;
        en_phys(e);
        return;
    }
    g_src = e;
    switch (e->type) {
    case ET_JAIL: en_jail(e); break;
    case ET_XBOW: en_xbow(e); break;
    case ET_RAT: en_rat(e); break;
    case ET_BRUTE: en_brute(e); break;
    case ET_SLIME: en_slime(e); break;
    case ET_GREN: en_gren(e); break;
    case ET_SHLD: en_shld(e); break;
    case ET_TOXIC: en_toxic(e); break;
    case ET_BAT: en_bat(e); break;
    case ET_GOB: en_gob(e); break;
    default: en_king(e); break;
    }
    g_src = 0;
    if (e->type != ET_BAT) en_phys(e);
}

/* ================================================================= projectiles */
static void explode(Proj *p) {
    int x = PX(p->x), y = PX(p->y);
    add_fx(SB_FX_EXPL, SN_FX_EXPL, x, y, 3);
    G.shake = imax(G.shake, 4);
    g_pierce = 1;                                                       /* le souffle ignore les boucliers */
    if (p->owner == 0 || p->type == PJ_FIRE) {
        for (int i = 0; i < MAX_EN; i++) {
            Ent *e = &G.en[i];
            if (!e->alive || e->st == ES_DEAD || e->st == ES_SLEEP) continue;
            if (iabs(PX(e->x) - x) < 30 && iabs(PX(e->y) - ED[e->type].h / 2 - y) < 28) {
                hurt_enemy(e, p->dmg, p->dir, 2, 8);
                if (p->type == PJ_FIRE && e->st != ES_DEAD) e->burn = 90;
            }
        }
    } else if (iabs(PX(G.p.x) - x) < 34 && iabs(PX(G.p.y) - 10 - y) < 30) hurt_player(p->dmg, x, 5);
    g_pierce = 0;
    p->life = 0;
}

static void proj_update(void) {
    for (int i = 0; i < MAX_PR; i++) {
        Proj *p = &G.pr[i];
        if (!p->life) continue;
        p->life--; p->anim++;
        if (p->type == PJ_SPIT) p->vy += 5;
        if (p->type == PJ_BOMB) p->vy += 6;
        p->x += p->vx; p->y += p->vy;
        int x = PX(p->x), y = PX(p->y);
        if (p->type == PJ_CLOUD) {                                      /* nuage de poison : immobile, degats sur la duree */
            if (player_box_overlap(x - 14, y - 16, 28, 16)) hurt_player(p->dmg, x, 0);
            continue;
        }
        if (x < 0 || x > G.lvw * TS || y > (LV_H + 2) * TS || y < 0) { p->life = 0; continue; }
        if (is_solid(tile_at(x >> 4, (p->type == PJ_WAVE ? y - 4 : y) >> 4))) {
            if (p->type == PJ_FIRE || p->type == PJ_BOMB) explode(p);
            else { if (p->type != PJ_WAVE) burst(x, y, 3, 0); p->life = 0; }
            continue;
        }
        if (p->type == PJ_BOMB && p->life == 0) { explode(p); continue; }
        if (p->owner == 0 && p->type != PJ_BOMB) {
            for (int k = 0; k < MAX_EN; k++) {
                Ent *e = &G.en[k];
                if (!e->alive || e->st == ES_DEAD || e->st == ES_SLEEP || (p->hm & (1u << k))) continue;
                int ex = PX(e->x), ey = PX(e->y);
                if (iabs(x - ex) < ED[e->type].w / 2 + 4 && y > ey - ED[e->type].h - 2 && y < ey + 2) {
                    if (p->type == PJ_FIRE) { explode(p); break; }
                    p->hm |= (1u << k);
                    g_pierce = (uint8_t)(p->type == PJ_XBOLT);          /* l'arbalete perce les boucliers */
                    hurt_enemy(e, p->dmg, p->dir, p->type == PJ_PARROW ? 4 : 2, p->type == PJ_PARROW ? 14 : 6);
                    g_pierce = 0;
                    if (p->pierce == 0) { p->life = 0; break; }
                    p->pierce--;
                }
            }
        } else if (p->owner == 1 || p->type == PJ_BOMB) {
            int hw = (p->type == PJ_WAVE) ? 7 : (p->type == PJ_SPIT ? 4 : 6);
            int y0 = (p->type == PJ_WAVE) ? y - 14 : y - 3, h = (p->type == PJ_WAVE) ? 14 : 6;
            if (p->owner == 1 && player_box_overlap(x - hw, y0, hw * 2, h)) {
                if (p->type != PJ_WAVE && player_parry_window(x)) {     /* PARADE : le projectile est renvoye */
                    p->owner = 0; p->vx = -p->vx; p->vy = -p->vy / 2; p->dir = (int8_t)-p->dir; p->dmg = (int16_t)(p->dmg * 2); p->hm = 0; p->life = 80;
                    burst(x, y, 8, 2); msg("PARADE !"); G.hitstop = 3;
                } else if (p->type == PJ_BOMB) explode(p);
                else { hurt_player(p->dmg, x, 3); if (p->type != PJ_WAVE) p->life = 0; }
            } else if (p->owner == 0 && p->type == PJ_BOMB) {          /* bombe renvoyee : touche un ennemi */
                for (int k = 0; k < MAX_EN; k++) {
                    Ent *e = &G.en[k];
                    if (e->alive && e->st != ES_DEAD && e->st != ES_SLEEP && iabs(x - PX(e->x)) < ED[e->type].w / 2 + 6 && y > PX(e->y) - ED[e->type].h - 4 && y < PX(e->y) + 2) { explode(p); break; }
                }
            }
        }
    }
}

/* ================================================================= objets ramassables */
static void take_weapon(const Item *it) {
    Player *p = &G.p;
    char buf[32], lab[8]; const char *nm = WPN[it->id].name; int i = 0;
    if (it->id == WP_SCYTHE) { p->w[0] = *it; p->w[1] = *it; }                 /* arme double : occupe les deux emplacements */
    else {
        p->w[p->cur] = *it;
        if (p->w[p->cur ^ 1].id == WP_SCYTHE) {
            item_make(&p->w[p->cur ^ 1], random_weapon(it->id, WP_SCYTHE), 0, -1);
            if (p->w[p->cur ^ 1].id == WP_SCYTHE) p->w[p->cur ^ 1].id = WP_SWORD;
        }
    }
    item_label(it, lab);
    while (*nm && i < 22) buf[i++] = *nm++;
    buf[i++] = ' ';
    for (int j = 0; lab[j] && i < 31; j++) buf[i++] = lab[j];
    buf[i] = 0; msg(buf);
}

static void chest_open(Pick *k) {
    int x = PX(k->x), y = PX(k->y), r = rn(100);
    k->st = 1;
    if (r < 36) spawn_coins(x, y - 12, 12 + rn(14));
    else if (r < 52) add_pick(PK_HEART, x, y - 16, 0, 0, -60);
    else if (r < 62) add_pick(PK_FLASK, x, y - 16, 0, 0, -60);
    else if (r < 72) { drop_blueprint(x, y - 14); spawn_cells(x, y - 12, 2); }
    else { Item it; item_make(&it, random_weapon(G.p.w[0].id, G.p.w[1].id), rn(2), -1); add_item_pick(x, y - 16, &it, -70); }
    burst(x, y - 10, 10, 2);
    add_fx(SB_FX_HIT, SN_FX_HIT, x, y - 10, 2);
}

static void pick_update(void) {
    Player *p = &G.p;
    for (int i = 0; i < MAX_PK; i++) {
        Pick *k = &G.pk[i];
        if (!k->life || k->kind == PK_NPC) continue;
        int x = PX(k->x), y = PX(k->y);
        if (k->kind == PK_CHEST) {
            if (!k->st && p->st != PS_DEAD && player_box_overlap(x - 8, y - 14, 16, 14)) chest_open(k);
            continue;
        }
        int magnet = 0;
        if ((k->kind == PK_COIN || k->kind == PK_CELL) && p->st != PS_DEAD) {
            int dx = PX(p->x) - x, dy = (PX(p->y) - 10) - (y - 3);
            if (iabs(dx) < 44 && iabs(dy) < 36) { k->x += clampi(dx, -3, 3) * 16; k->y += clampi(dy, -3, 3) * 16; magnet = 1; }
        }
        if (!magnet) {
            k->vy = imin(k->vy + 6, 100);
            int vyb = (int)k->vy;
            int fl = move_box(&k->x, &k->y, &k->vx, &k->vy, 6, 6, 0);
            if (fl & MB_GROUND) { k->vx = k->vx * 3 / 4; if (vyb > 40) k->vy = -vyb / 3; }
        }
        x = PX(k->x); y = PX(k->y);
        if (y > (LV_H + 2) * TS) { k->life = 0; continue; }
        if (p->st == PS_DEAD || !player_box_overlap(x - 4, y - 8, 8, 8)) continue;
        switch (k->kind) {
        case PK_COIN: G.run_gold += imax(1, k->val); k->life = 0; break;
        case PK_CELL: G.cells_run += k->val; k->life = 0; break;
        case PK_BLUE: G.bp_carry |= (uint16_t)(1 << k->val); msg("SCH" EAC "MA TROUV" EAC " !"); k->life = 0; break;
        case PK_HEART:
            if (p->hp < p->maxhp) { int h = p->maxhp / 5; p->hp = (int16_t)imin(p->maxhp, p->hp + h); add_num(PX(p->x), PX(p->y) - 26, h, 3); k->life = 0; }
            break;
        case PK_FLASK:
            if (p->flasks < p->maxflasks) { p->flasks++; msg("FIOLE +1"); k->life = 0; }
            break;
        case PK_WPN: { Item it; it.id = k->val; it.lvl = k->lvl ? k->lvl : 1; it.q = k->q; take_weapon(&it); k->life = 0; break; }
        default: break;
        }
    }
}

/* ================================================================= particules */
void part_update(void) {
    for (int i = 0; i < MAX_PA; i++) {
        Part *a = &G.pa[i];
        if (!a->life) continue;
        a->life--;
        switch (a->kind) {
        case PA_SPARK: a->vy = (int16_t)(a->vy + 3); a->x += a->vx; a->y += a->vy; break;
        case PA_SMOKE: a->x += a->vx; a->y += a->vy; a->vx = (int16_t)(a->vx * 7 / 8); break;
        case PA_EMBER: a->x += a->vx; a->y += a->vy; break;
        case PA_NUM: a->y += a->vy; a->vy = (int16_t)(a->vy * 9 / 10); break;
        default: break;
        }
    }
}

void ai_update(void) {
    for (int i = 0; i < MAX_EN; i++) enemy_update(&G.en[i]);
    proj_update();
    pick_update();
    part_update();
}

void kill_all_for_test(void) {
    for (int i = 0; i < MAX_EN; i++) if (G.en[i].alive && G.en[i].st != ES_DEAD) { G.en[i].hp = 1; hurt_enemy(&G.en[i], 9999, 1, 0, 0); }
}

/* ======== dc_render.c ======== */
/* dc_render.c - rendu par bandes de 16 lignes (320x16 pixels RGB565) : aucun tampon plein ecran en RAM. */

#define C565(r, g, b) ((uint16_t)((((r) >> 3) << 11) | (((g) >> 2) << 5) | ((b) >> 3)))
#define C_WHITE  C565(255, 255, 255)
#define C_SHADOW C565(10, 8, 20)
#define C_GOLD   C565(255, 214, 80)
#define C_RED    C565(224, 64, 64)
#define C_GREEN  C565(120, 232, 90)
#define C_CYAN   C565(110, 190, 255)
#define C_GREY   C565(150, 150, 170)
#define C_ORANGE C565(255, 150, 50)
#define C_PANEL  C565(18, 14, 34)
#define C_PANEL2 C565(40, 32, 70)

static uint16_t *S;
static int SY;

static void px(int x, int y, uint16_t c) { if ((unsigned)x < SCR_W && (unsigned)(y - SY) < STRIP_H) S[(y - SY) * SCR_W + x] = c; }
static void rect(int x, int y, int w, int h, uint16_t c) {
    int y0 = y < SY ? SY : y, y1 = (y + h > SY + STRIP_H) ? SY + STRIP_H : y + h;
    int x0 = x < 0 ? 0 : x, x1 = (x + w > SCR_W) ? SCR_W : x + w;
    for (int yy = y0; yy < y1; yy++) { uint16_t *d = S + (yy - SY) * SCR_W; for (int xx = x0; xx < x1; xx++) d[xx] = c; }
}
static uint16_t lit(uint16_t c, int a) {
    int r = (c >> 11) + a, g = ((c >> 5) & 63) + a * 2, b = (c & 31) + a;
    if (r > 31) r = 31;
    if (g > 63) g = 63;
    if (b > 31) b = 31;
    return (uint16_t)((r << 11) | (g << 5) | b);
}
static uint16_t tint_red(uint16_t c) { int r = ((c >> 11) & 31) + 12; if (r > 31) r = 31; return (uint16_t)((c & 0x07FF) | (r << 11)); }

/* ---------------------------------------------------------------- texte (police 5x7 + accents, agrandie par entier) */
static int tw(const char *s, int sc) { int n = 0; while (s[n]) n++; return n * 6 * sc; }
static void text(int x, int y, const char *s, uint16_t c, int sc) {
    if (y + 8 * sc < SY || y - sc >= SY + STRIP_H) return;
    for (; *s; s++, x += 6 * sc) {
        int ch = (uint8_t)*s;
        if (ch >= 'a' && ch <= 'z') ch -= 32;
        if (ch >= 144) ch = ' ';
        const uint8_t *g = FONT9[ch];
        for (int r = 0; r < 9; r++) {
            int b = g[r], yy = y + (r - 1) * sc;
            if (!b || yy + sc <= SY || yy >= SY + STRIP_H) continue;
            for (int i = 0; i < 5; i++) if (b & (16 >> i)) rect(x + i * sc, yy, sc, sc, c);
        }
    }
}
static void text_sh(int x, int y, const char *s, uint16_t c, int sc) { text(x + sc, y + sc, s, C_SHADOW, sc); text(x, y, s, c, sc); }
static void text_c(int cx, int y, const char *s, uint16_t c, int sc) { text_sh(cx - tw(s, sc) / 2, y, s, c, sc); }
static char *i2s(int v, char *o) {                     /* o doit contenir au moins 12 octets */
    char t[12]; int n = 0, i = 0, neg = v < 0;
    if (neg) v = -v;
    do { t[n++] = (char)('0' + v % 10); v /= 10; } while (v);
    if (neg) o[i++] = '-';
    while (n) o[i++] = t[--n];
    o[i] = 0; return o;
}
static void cat(char *d, const char *s) { while (*d) d++; while ((*d++ = *s++)) {} }

/* ---------------------------------------------------------------- sprites */
static void spr(int id, int x, int y, int flip, int mode, int skin) {
    const Spr *sp = &SPR[id]; int w = sp->w, h = sp->h;
    int y0 = y > SY ? y : SY, y1 = (y + h < SY + STRIP_H) ? y + h : SY + STRIP_H;
    if (y0 >= y1 || x >= SCR_W || x + w <= 0) return;
    const uint8_t *base = SPRDATA + sp->off;
    for (int yy = y0; yy < y1; yy++) {
        const uint8_t *row = base + (yy - y) * w;
        uint16_t *dst = S + (yy - SY) * SCR_W;
        for (int i = 0; i < w; i++) {
            int dx = x + i;
            if ((unsigned)dx >= SCR_W) continue;
            uint8_t c = row[flip ? (w - 1 - i) : i];
            if (!c) continue;
            if (skin && c >= ACC_LO && c < ACC_LO + 3) c = SKINMAP[skin][c - ACC_LO];
            uint16_t col = PAL565[c];
            if (mode == 1) col = C_WHITE; else if (mode == 2) col = tint_red(col);
            dst[dx] = col;
        }
    }
}
static void spr2x(int id, int x, int y, int flip) {                /* agrandissement x2 (ecran titre) */
    const Spr *sp = &SPR[id]; int w = sp->w, h = sp->h; const uint8_t *base = SPRDATA + sp->off;
    for (int yy = y; yy < y + 2 * h; yy++) {
        if (yy < SY || yy >= SY + STRIP_H) continue;
        const uint8_t *row = base + ((yy - y) >> 1) * w;
        for (int i = 0; i < 2 * w; i++) {
            uint8_t c = row[flip ? (w - 1 - (i >> 1)) : (i >> 1)];
            if (c) px(x + i, yy, PAL565[c]);
        }
    }
}
static void spr_f(int id, int x, int y, int ax, int flip, int mode, int skin) {   /* ancre pieds : (x,y) = centre-bas */
    const Spr *sp = &SPR[id];
    spr(id, flip ? x - (sp->w - 1 - ax) : x - ax, y - sp->h + 1, flip, mode, skin);
}

/* ---------------------------------------------------------------- fond */
static int hash2(int a, int b) { unsigned h = (unsigned)a * 374761393u + (unsigned)b * 668265263u; h = (h ^ (h >> 13)) * 1274126177u; return (int)(h >> 16); }

static void draw_sky(int camx, int z) {
    const uint16_t *zc = ZCOL[z];
    for (int yy = SY; yy < SY + STRIP_H; yy++) {
        uint16_t c = yy < 70 ? zc[0] : (yy < 130 ? lit(zc[0], 2) : (yy < 180 ? zc[1] : zc[2]));
        rect(0, yy, SCR_W, 1, c);
    }
    for (int i = 0; i < 40; i++) {                                    /* etoiles */
        int x = hash2(i, 1) % 400 - (camx / 8) % 400, y = hash2(i, 2) % 150;
        if (x < 0) x += 400;
        if (x < SCR_W && (((G.frame >> 4) + i) & 7)) px(x, y, i & 3 ? C565(200, 210, 255) : C_WHITE);
    }
    int mx = 240 - (camx / 10) % 400;                                  /* lune */
    for (int yy = SY; yy < SY + STRIP_H; yy++) for (int xx = mx - 14; xx <= mx + 14; xx++)
        if ((xx - mx) * (xx - mx) + (yy - 50) * (yy - 50) <= 196 && ((xx - mx + 6) * (xx - mx + 6) + (yy - 46) * (yy - 46)) > 150) px(xx, yy, C565(240, 232, 200));
    int sc = camx / 4;                                                 /* tours lointaines */
    for (int xx = 0; xx < SCR_W; xx++) {
        int k = ((xx + sc) >> 4) & 15, hgt = 70 + (hash2(k, 7) % 4) * 14;
        if (hash2(k, 9) & 1) hgt -= 30;
        if (SY + STRIP_H > 240 - hgt) for (int yy = (240 - hgt > SY ? 240 - hgt : SY); yy < SY + STRIP_H; yy++) px(xx, yy, ZCOL[z][1]);
    }
}

static void draw_bg(int camx) {
    int z = G.zone;
    if (z == 3) { draw_sky(camx, 3); return; }
    const uint8_t *t = SPRDATA + SPR[SB_BGT + z].off;
    int sc = camx / 2;
    for (int yy = SY; yy < SY + STRIP_H; yy++) {
        const uint8_t *row = t + (yy & 31) * 32;
        uint16_t *d = S + (yy - SY) * SCR_W;
        for (int xx = 0; xx < SCR_W; xx++) d[xx] = PAL565[row[(xx + sc) & 31]];
    }
    int per = 160, first = sc / per - 1;                                /* decor lointain tous les 160 px */
    for (int k = first; k < first + 4; k++) spr(SB_BGD + z, k * per + 64 - sc, 30, 0, 0, 0);
}

static void draw_glow(int camx) {
    if (!G.sv.opt_fx) return;
    for (int i = 0; i < G.torch_n; i++) {
        int cx = G.torch_x[i] - camx, cy = G.torch_y[i], R = 46, R2 = R * R;
        if (cx < -R || cx > SCR_W + R) continue;
        for (int yy = SY; yy < SY + STRIP_H; yy++) {
            int dy = yy - cy; if (dy < -R || dy > R) continue;
            uint16_t *d = S + (yy - SY) * SCR_W;
            for (int xx = (cx - R < 0 ? 0 : cx - R); xx <= cx + R && xx < SCR_W; xx++) {
                int d2 = (xx - cx) * (xx - cx) + dy * dy;
                if (d2 < R2) d[xx] = lit(d[xx], 1 + ((R2 - d2) * 5 / R2) + (((G.frame >> 2) + i) & 1));
            }
        }
    }
}

static void draw_tiles(int camx) {
    int ty = SY / TS, z = G.zone;
    if (ty >= LV_H) return;
    for (int tx = camx / TS; tx <= (camx + SCR_W - 1) / TS && tx < G.lvw; tx++) {
        if (tx < 0) continue;
        int t = G.map[ty][tx], sx = tx * TS - camx;
        switch (t) {
            case TL_SOLID: case TL_GATE:
                if (t == TL_GATE) { spr(SB_TL_GATE, sx, SY, 0, 0, 0); break; }
                spr(SB_TL_SOLID + z * 3 + (hash2(tx, ty) & 3) % 3, sx, SY, 0, 0, 0);
                if (ty > 0 && !is_solid(G.map[ty - 1][tx])) spr(SB_TL_CAP + z, sx, SY, 0, 0, 0);
                break;
            case TL_PLAT: spr(SB_TL_PLAT + z, sx, SY, 0, 0, 0); break;
            case TL_SPIKE: spr(SB_TL_SPIKE, sx, SY, 0, 0, 0); break;
            case TL_TOXIC: spr(SB_TL_TOXIC + ((G.frame >> 3) & 1), sx, SY, 0, 0, 0); break;
            case TL_TORCH: spr(SB_TL_TORCH + ((G.frame >> 2) % 3), sx + 4, SY, 0, 0, 0); break;
            case TL_DOOR: spr(SB_TL_DOOR, sx, SY - TS, 0, 0, 0); break;
            default: break;
        }
        if (ty + 1 < LV_H && G.map[ty + 1][tx] == TL_DOOR) spr(SB_TL_DOOR, sx, SY, 0, 0, 0);   /* moitie haute de la porte */
    }
}

/* ---------------------------------------------------------------- entites */
static const uint8_t ACX[ET_COUNT] = { 14, 14, 14, 20, 11, 14, 14, 14, 16, 26, 22 };

static int esp(const Ent *e) {
    int a = e->anim, mv = e->vx != 0, t = e->t;
    switch (e->type) {
    case ET_JAIL:  return e->st == ES_DEAD ? SB_JAIL_DEAD + (t > 8) : e->st == ES_HURT ? SB_JAIL_HURT : e->st == ES_WIND ? SB_JAIL_WIND : e->st == ES_ATK ? SB_JAIL_SWING : mv ? SB_JAIL_WALK + ((a >> 2) & 3) : SB_JAIL_IDLE;
    case ET_XBOW:  return e->st == ES_DEAD ? SB_XBOW_DEAD + (t > 8) : e->st == ES_HURT ? SB_XBOW_HURT : e->st == ES_WIND ? SB_XBOW_AIM : (e->st == ES_REC && t > 8) ? SB_XBOW_SHOOT : mv ? SB_XBOW_WALK + ((a >> 2) & 3) : SB_XBOW_IDLE;
    case ET_RAT:   return e->st == ES_DEAD ? SB_RAT_DEAD + (t > 8) : e->st == ES_HURT ? SB_RAT_HURT : e->st == ES_ATK ? SB_RAT_LEAP : SB_RAT_RUN + (mv ? ((a >> 1) & 3) : 0);
    case ET_BRUTE: return e->st == ES_DEAD ? SB_BRUTE_DEAD + (t > 8) : e->st == ES_HURT ? SB_BRUTE_HURT : e->st == ES_WIND ? SB_BRUTE_WIND : e->st == ES_ATK ? SB_BRUTE_SLAM : mv ? SB_BRUTE_WALK + ((a >> 3) & 3) : SB_BRUTE_IDLE;
    case ET_SLIME: return e->st == ES_DEAD ? SB_SLIME_DEAD + (t > 8) : e->st == ES_HURT ? SB_SLIME_HURT : e->st == ES_AIR ? SB_SLIME_HOP : SB_SLIME_IDLE + ((a >> 4) & 1);
    case ET_GREN:  return e->st == ES_DEAD ? SB_GREN_DEAD + (t > 8) : e->st == ES_HURT ? SB_GREN_HURT : e->st == ES_WIND ? SB_GREN_WIND : (e->st == ES_REC && t > 7) ? SB_GREN_THROW : mv ? SB_GREN_WALK + ((a >> 2) & 3) : SB_GREN_IDLE;
    case ET_SHLD:  return e->st == ES_DEAD ? SB_SHLD_DEAD + (t > 8) : e->st == ES_HURT ? SB_SHLD_HURT : e->st == ES_WIND ? SB_SHLD_WIND : e->st == ES_ATK ? SB_SHLD_BASH : mv ? SB_SHLD_WALK + ((a >> 3) & 3) : SB_SHLD_IDLE;
    case ET_TOXIC: return e->st == ES_DEAD ? SB_TOXIC_DEAD + (t > 8) : e->st == ES_HURT ? SB_TOXIC_HURT : e->st == ES_ATK ? SB_TOXIC_ATK : mv ? SB_TOXIC_WALK + ((a >> 3) & 3) : SB_TOXIC_IDLE;
    case ET_BAT:   return e->st == ES_DEAD ? SB_BAT_DEAD + (t > 8) : e->st == ES_HURT ? SB_BAT_HURT : e->st == ES_ATK ? SB_BAT_DIVE : SB_BAT_FLY + ((a >> 1) & 3);
    case ET_GOB:
        if (e->st == ES_DEAD) return SB_GOB_DEAD + (t > 25);
        if (e->st == ES_AIR) return (e->aux == 2 && e->t == 1) ? SB_GOB_SLAM : SB_GOB_HOP;
        if (e->st == ES_WIND) return e->aux == 1 ? SB_GOB_SPIT : SB_GOB_SLAM;
        if (e->st == ES_REC) return t > 10 ? (e->aux == 1 ? SB_GOB_SPIT : SB_GOB_SLAM) : SB_GOB_IDLE;
        return SB_GOB_IDLE + ((a >> 4) & 1);
    default:
        if (e->st == ES_DEAD) return SB_KING_DEAD + (t > 35 ? 2 : t > 15 ? 1 : 0);
        if (e->st == ES_WIND) return e->aux == 0 ? SB_KING_CWIND : e->aux == 1 ? SB_KING_SWIND : SB_KING_SLWIND;
        if (e->st == ES_ATK) return e->aux == 0 ? SB_KING_DASH : e->aux == 1 ? SB_KING_SWEEP : SB_KING_SLAM;
        if (e->st == ES_REC) return e->aux == 2 ? SB_KING_SLAM : (e->aux == 0 && t > 22) ? SB_KING_HURT : SB_KING_IDLE;
        return mv ? SB_KING_WALK + ((a >> 3) & 3) : SB_KING_IDLE + ((a >> 4) & 1);
    }
}

static void draw_enemy(const Ent *e, int camx) {
    if (!e->alive) return;
    int x = PX(e->x) - camx, y = PX(e->y);
    if (x < -70 || x > SCR_W + 70) return;
    int mode = e->flash > 0 ? 1 : (e->elite && ((G.frame >> 3) & 1)) ? 2 : 0;
    if (e->type == ET_BAT) { const Spr *sp = &SPR[esp(e)]; spr(esp(e), e->dir < 0 ? x - (sp->w - 1 - 16) : x - 16, y - 15, e->dir < 0, mode, 0); return; }
    spr_f(esp(e), x, y, ACX[e->type], e->dir < 0, mode, e->skin);
    if (e->burn > 0 && (G.frame & 2)) px(x + (hash2(G.frame, e->type) % 7) - 3, y - ent_h(e) - (G.frame & 3), C_ORANGE);
}

static void draw_player(int camx) {
    Player *p = &G.p;
    int x = PX(p->x) - camx, y = PX(p->y), id, flip = p->dir < 0, mode = 0;
    const Wpn *w = &WPN[p->w[p->cur].id];
    if (p->st == PS_DEAD) id = SB_HERO_DEAD + (p->dead_t > 24 ? 2 : p->dead_t > 8 ? 1 : 0);
    else if (p->st == PS_HURT) id = SB_HERO_HURT;
    else if (p->st == PS_ROLL) id = SB_HERO_ROLL + ((p->t >> 1) & 3);
    else if (p->st == PS_ATK) {
        const Atk *a = p->atk_b ? &w->b : (p->heavy ? &w->h : &w->l);
        int f = p->atk_t < a->a0 ? 0 : (p->atk_t <= a->a1 ? 1 : 2);
        switch (w->kind) {
            case WK_BOW: id = SB_HERO_BOW + (f > 0); break;
            case WK_FIRE: case WK_ELEC: id = SB_HERO_CAST + (f > 0); break;
            case WK_DUAL: id = p->atk_b ? SB_HERO_DAGGER + (f > 0) : SB_HERO_SWORD + f; break;
            case WK_SHIELD: id = SB_HERO_DAGGER + (f > 0); break;
            default:
                switch (p->w[p->cur].id) {
                    case WP_DAGGER: case WP_RAPIER: id = SB_HERO_DAGGER + (f > 0); break;
                    case WP_HAMMER: id = SB_HERO_HAMMER + f; break;
                    default: id = SB_HERO_SWORD + f; break;
                }
        }
    }
    else if (!p->ground) id = (p->jumps == 2 && p->flip_t > 0) ? SB_HERO_FLIP + ((p->flip_t >> 3) & 1) : (p->vy < 0 ? SB_HERO_JUMP : SB_HERO_FALL);
    else if (p->vx != 0) id = SB_HERO_RUN + ((p->anim / 3) % 6);
    else id = SB_HERO_IDLE + ((p->anim >> 4) & 1);
    if (p->hold >= 14 && (G.frame & 2)) mode = 1;                       /* charge prete : clignote */
    if (p->inv > 0 && p->st != PS_ROLL && p->st != PS_DEAD && (G.frame & 2)) return;
    spr_f(id, x, y, 14, flip, mode, 0);
    if (p->guard) {                                                     /* bouclier leve devant le heros */
        spr(SB_IT_WPN + WP_SHIELD, x + p->dir * 8 - 8, y - 24, 0, p->guard_t <= 8 ? 1 : 0, 0);
    }
}

static void draw_projectiles(int camx) {
    for (int i = 0; i < MAX_PR; i++) {
        const Proj *p = &G.pr[i];
        if (!p->life) continue;
        int x = PX(p->x) - camx, y = PX(p->y), fl = p->vx < 0;
        switch (p->type) {
            case PJ_ARROW: case PJ_PARROW: spr(SB_FX_ARROW, x - 8, y - 2, fl, 0, 0); break;
            case PJ_BOLT: case PJ_XBOLT: spr(SB_FX_BOLT, x - 6, y - 2, fl, 0, 0); break;
            case PJ_FIRE: spr(SB_FX_FIRE + ((p->anim >> 1) & 3), x - 8, y - 8, fl, 0, 0); break;
            case PJ_SPIT: spr(SB_FX_SPIT + ((p->anim >> 2) & 1), x - 4, y - 4, 0, 0, 0); break;
            case PJ_WAVE: spr(SB_FX_WAVE + ((p->anim >> 2) & 1), x - 8, y - 15, fl, 0, 0); break;
            case PJ_BOMB: spr(SB_FX_BOMB + ((p->anim >> 2) & 1), x - 4, y - 4, 0, 0, 0); break;
            default: spr(SB_FX_CLOUD + ((p->anim >> 3) & 1), x - 12, y - 16, 0, 0, 0); break;
        }
    }
}

static void draw_line(int x0, int y0, int x1, int y1, uint16_t c) {
    int dx = x1 > x0 ? x1 - x0 : x0 - x1, dy = y1 > y0 ? y0 - y1 : y1 - y0, sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1, err = dx + dy;
    for (int n = 0; n < 600; n++) {
        px(x0, y0, c);
        if (x0 == x1 && y0 == y1) break;
        int e2 = 2 * err;
        if (e2 >= dy) { err += dy; x0 += sx; }
        if (e2 <= dx) { err += dx; y0 += sy; }
    }
}

static void draw_particles(int camx) {
    for (int i = 0; i < MAX_PA; i++) {
        const Part *a = &G.pa[i];
        if (!a->life) continue;
        int x = PX(a->x) - camx, y = PX(a->y);
        switch (a->kind) {
            case PA_SPARK: { uint16_t c = a->col == 1 ? C_RED : a->col == 2 ? C_GOLD : a->col == 3 ? C_GREEN : C565(255, 240, 200); rect(x, y, 2, 2, c); break; }
            case PA_SMOKE: rect(x, y, 3, 3, C565(140, 140, 160)); break;
            case PA_EMBER: px(x, y, C_ORANGE); break;
            case PA_FX: { int f = (a->max - a->life) / (a->val ? a->val : 1); if (f >= a->nf) f = a->nf - 1;
                const Spr *sp = &SPR[a->num + f]; spr(a->num + f, x - sp->w / 2, y - sp->h / 2, a->col, 0, 0); break; }
            case PA_NUM: { char b[12]; uint16_t c = a->col == 1 ? C_RED : a->col == 3 ? C_GREEN : a->col == 4 ? C_ORANGE : C_WHITE; i2s(a->num, b); text_sh(x - tw(b, 1) / 2, y, b, c, 1); break; }
            case PA_LINE: {
                int x1 = a->vx - camx, y1 = a->vy, mx = (x + x1) / 2 + ((G.frame * 7 + i) % 9 - 4), my = (y + y1) / 2 + ((G.frame * 5 + i) % 9 - 4);
                draw_line(x, y, mx, my, C565(200, 232, 255)); draw_line(mx, my, x1, y1, C565(120, 190, 255)); break; }
            default: break;
        }
    }
}

static void draw_picks(int camx) {
    for (int i = 0; i < MAX_PK; i++) {
        const Pick *k = &G.pk[i];
        if (!k->life) continue;
        int x = PX(k->x) - camx, y = PX(k->y), bob = (G.frame >> 3) & 1;
        if (x < -30 || x > SCR_W + 30) continue;
        switch (k->kind) {
            case PK_COIN: spr(SB_IT_COIN + ((G.frame >> 2) & 3), x - 4, y - 8, 0, 0, 0); break;
            case PK_CELL: spr(SB_IT_CELL + ((G.frame >> 3) & 1), x - 4, y - 8, 0, 0, 0); break;
            case PK_HEART: spr(SB_IT_HEART, x - 5, y - 10 - bob, 0, 0, 0); break;
            case PK_FLASK: spr(SB_IT_FLASK, x - 5, y - 12 - bob, 0, 0, 0); break;
            case PK_BLUE: spr(SB_IT_BLUEPRINT, x - 5, y - 12 - bob, 0, 0, 0); break;
            case PK_WPN: { char lab[8]; Item it; it.id = k->val; it.lvl = k->lvl ? k->lvl : 1; it.q = k->q; item_label(&it, lab);
                spr(SB_IT_WPN + k->val, x - 8, y - 18 - bob, 0, 0, 0); text_sh(x - tw(lab, 1) / 2, y - 29, lab, it.q == 4 ? C_ORANGE : C_GOLD, 1); break; }
            case PK_CHEST: spr(SB_IT_CHEST + k->st, x - 8, y - 13, 0, 0, 0); break;
            default: {                                                  /* PNJ */
                int base = k->val ? SB_NPC_ORACLE : SB_NPC_PASSEUR;
                spr(base + ((G.frame >> 4) & 1), x - 12, y - 31, 0, 0, 0);
                if (iabs(PX(G.p.x) - PX(k->x)) < 22) text_sh(x - 6, y - 42, "OK", C_GOLD, 1);
                break; }
        }
    }
}

/* ---------------------------------------------------------------- monde */
static void draw_world(void) {
    int sh = G.shake > 0 ? ((G.frame & 1) ? G.shake / 2 : -G.shake / 2) : 0, camx = PX(G.cam_x) + sh;
    draw_bg(camx);
    draw_tiles(camx);
    draw_picks(camx);
    for (int i = 0; i < MAX_EN; i++) draw_enemy(&G.en[i], camx);
    draw_player(camx);
    draw_projectiles(camx);
    draw_particles(camx);
    draw_glow(camx);
}

/* ---------------------------------------------------------------- interface */
static void dim(void) { for (int i = 0; i < SCR_W * STRIP_H; i++) S[i] = (uint16_t)((S[i] >> 1) & 0x7BEF); }
static void fill_bg(uint16_t c) { rect(0, SY, SCR_W, STRIP_H, c); }
static void draw_bar(int x, int y, int w, int h, int v, int max, uint16_t c, uint16_t back) {
    int f = max > 0 ? v * w / max : 0;
    if (f < 0) f = 0;
    if (f > w) f = w;
    rect(x - 2, y - 2, w + 4, h + 4, C_SHADOW); rect(x, y, w, h, back);
    rect(x, y, f, h, c); rect(x, y, f, h / 3 + 1, lit(c, 8));
}
static void price_at(int right, int y, int price, int gold) {
    char b[12];
    if (price < 0) { text_sh(right - tw("MAX", 2), y, "MAX", C_GOLD, 2); return; }
    i2s(price, b);
    spr(gold ? SB_IT_COIN : SB_IT_CELL, right + 4, y + 3, 0, 0, 0);
    text_sh(right - tw(b, 2), y, b, gold ? C_GOLD : C_CYAN, 2);
}

static void draw_hud(void) {
    Player *p = &G.p; char b[16], t[16];
    text_sh(6, 5, HEARTC, C_RED, 2);
    draw_bar(26, 8, 100, 10, p->hp, p->maxhp, C_RED, C565(60, 20, 30));
    i2s(p->hp, b); cat(b, "/"); cat(b, i2s(p->maxhp, t)); text_sh(134, 5, b, C_WHITE, 2);
    spr(SB_IT_COIN + ((G.frame >> 2) & 3), 232, 7, 0, 0, 0); text_sh(246, 4, i2s((int)G.run_gold, b), C_GOLD, 2);
    spr(SB_IT_CELL + ((G.frame >> 3) & 1), 232, 25, 0, 0, 0); text_sh(246, 21, i2s((int)G.cells_run, b), C_CYAN, 2);
    if (G.boss_alive && G.boss_idx >= 0 && G.en[G.boss_idx].alive)
        draw_bar(70, 46, 180, 8, G.en[G.boss_idx].hp, G.en[G.boss_idx].maxhp, C565(200, 40, 200), C565(40, 10, 40));
    for (int s = 0; s < 2; s++) {
        int x0 = 6 + s * 32;
        char lab[8]; item_label(&p->w[s], lab);
        rect(x0 - 1, 205, 28, 28, s == p->cur ? C_GOLD : C_GREY); rect(x0, 206, 26, 26, C_PANEL);
        spr(SB_IT_WPN + p->w[s].id, x0 + 5, 210, 0, 0, 0);
        text_sh(x0 + 13 - tw(lab, 1) / 2, 233, lab, p->w[s].q == 4 ? C_ORANGE : C_GOLD, 1);
    }
    spr(SB_IT_FLASK, 76, 210, 0, 0, 0); b[0] = 'X'; i2s(p->flasks, b + 1); text_sh(90, 208, b, C_WHITE, 2);
    if (G.banner_t > 0) text_c(160, 64, G.banner, C_WHITE, 2);
    if (G.msg_t > 0) text_c(160, G.passage ? 124 : 184, G.msg, C_GOLD, 2);
    if (G.hint_t > 0) text_c(160, 150, "OK : ATTAQUE    RETOUR : ESQUIVE", C_WHITE, 1);
    if (G.passage) { text_c(160, 100, "PARLE AUX PNJ AVEC OK", C_GOLD, 1); }
}

static void draw_title(void) {
    static const int cx_[6] = { 14, 62, 118, 196, 246, 284 }, cw_[6] = { 30, 26, 34, 28, 30, 24 }, ch_[6] = { 120, 150, 96, 142, 104, 126 };
    draw_sky(G.frame / 2, 4);
    for (int i = 0; i < 6; i++) {
        rect(cx_[i], 240 - ch_[i], cw_[i], ch_[i], C565(12, 8, 26));
        for (int k = 0; k < cw_[i] / 6; k++) rect(cx_[i] + k * 6, 240 - ch_[i] - 5, 4, 5, C565(12, 8, 26));
        for (int k = 0; k < 3; k++) if (hash2(i, k) & 1) rect(cx_[i] + 7 + k * 7, 240 - ch_[i] + 14 + k * 22, 3, 5, ((G.frame >> 5) + i + k) & 3 ? C_GOLD : C565(120, 70, 20));
    }
    rect(0, 212, SCR_W, 28, C565(8, 5, 18));
    for (int i = 0; i < 26; i++) { int x = hash2(i, 3) % 320, y = 240 - ((G.frame * (1 + i % 3) + hash2(i, 4)) % 260); rect(x, y, 2, 2, ((G.frame >> 3) + i) & 1 ? C_ORANGE : C565(255, 200, 80)); }
    spr2x(SB_HERO_IDLE + ((G.frame >> 5) & 1), 14, 150, 0);
    text_c(160, 18, "DEAD CELLS", C_ORANGE, 4);
    text_c(160, 56, "NUMWORKS EDITION", C_WHITE, 2);
    static const char *const TM[5] = { "JOUER", "BOUTIQUE", "OPTIONS", "COMMANDES", "QUITTER" };
    for (int i = 0; i < 5; i++) {
        int sel = (i == G.menu_sel), y = 92 + i * 22;
        text_c(160, y, TM[i], sel ? C_GOLD : C_GREY, 2);
        if (sel) { text_sh(160 - tw(TM[i], 2) / 2 - 20, y, ARIGHT, C_GOLD, 2); }
    }
    text_c(160, 224, "PROJET DE FAN NON OFFICIEL", C_GREY, 1);
    if (!G.save_ok) text_c(160, 212, "SAUVEGARDE INDISPONIBLE", C_RED, 1);
}

